const DATA={"exam":"2026-12-06","units":[{"n":1,"t":"안녕하세요?"},{"n":2,"t":"방에 책상이 있어요"},{"n":3,"t":"한국어를 배워요"},{"n":4,"t":"라흐만 씨가 식당에 가요"},{"n":5,"t":"오늘은 5월 5일이에요"},{"n":6,"t":"9시부터 6시까지 일해요"},{"n":7,"t":"김치찌개 하나 주세요"},{"n":8,"t":"칫솔하고 치약을 삽니다"},{"n":9,"t":"지난 주말에 친구를 만났어요"},{"n":10,"t":"아버지는 요리를 잘하세요"},{"n":11,"t":"어버이날에 부모님께 꽃을 드려요"},{"n":12,"t":"이번 휴가에 뭐 할 거예요?"},{"n":13,"t":"버스로 공항에 가요"},{"n":14,"t":"저녁 7시에 만날까요?"},{"n":15,"t":"오늘 날씨가 정말 덥네요"},{"n":16,"t":"배가 아파서 병원에 가요"},{"n":17,"t":"사진을 찍지 마세요"},{"n":18,"t":"한국 생활은 조금 힘든데 재미있어요"}],"words":[{"k":"공장 직원","e":"factory worker","x":"그분은 공장 직원이에요.","t":"He is a factory worker.","h":"직원 = staff/employee. 공장 = factory. Two-word job title.","y":0,"u":1},{"k":"국적","e":"nationality","x":"국적이 어디예요?","t":"What is your nationality?","h":"국적이 어디예요? = What is your nationality? 어디 (where) is used for 국적.","y":0,"u":1},{"k":"나라","e":"country","x":"어느 나라에서 왔어요?","t":"Which country are you from?","h":"Pairs with 어느: 어느 나라 = which country. 어느 always comes before a noun.","y":0,"u":1},{"k":"뉴욕","e":"New York","x":"뉴욕은 미국에 있어요.","t":"New York is in the USA.","h":"","y":0,"u":1},{"k":"미국","e":"USA","x":"제니 씨는 미국 사람이에요.","t":"Jenny is American.","h":"미국 사람 = American. Note: no 마국 - it is 미국 (mi-guk).","y":0,"u":1},{"k":"방글라데시","e":"Bangladesh","x":"라흐만 씨는 방글라데시 사람이에요.","t":"Rahman is Bangladeshi.","h":"","y":0,"u":1},{"k":"사람","e":"person","x":"저는 우즈베키스탄 사람이에요.","t":"I am from Uzbekistan.","h":"Nationality = country + 사람: 한국 사람, 미국 사람. Take 이에요/예요 after it.","y":0,"u":1},{"k":"선생님","e":"teacher","x":"우리 선생님은 한국 사람이에요.","t":"My teacher is Korean.","h":"Honorific 님 attached. For a teacher use 높임말: 선생님은, 선생님께서.","y":0,"u":1},{"k":"어느","e":"which","x":"어느 나라 사람이에요?","t":"Which country's person are you? / Where are you from?","h":"Question word for WHICH + noun: 어느 나라, 어느 사람. Not used alone.","y":0,"u":1},{"k":"영어","e":"English (language)","x":"영어를 잘해요?","t":"Do you speak English well?","h":"Language names end in 어: 영어, 한국어. 영어를 잘해요? = Do you speak English well?","y":0,"u":1},{"k":"영어 강사","e":"English instructor","x":"마이클 씨는 영어 강사예요.","t":"Michael is an English instructor.","h":"강사 = instructor/lecturer, not 선생님. Used for private academies (학원).","y":0,"u":1},{"k":"이름","e":"name","x":"이름이 뭐예요?","t":"What is your name?","h":"이름이 뭐예요? is the classic first question. 뭐예요 = what is it?","y":0,"u":1},{"k":"이집트","e":"Egypt","x":"사미 씨는 이집트에서 왔어요.","t":"Sami came from Egypt.","h":"Loanword from Egypt.에서 왔어요 = came from: 이집트에서 왔어요.","y":0,"u":1},{"k":"주부","e":"homemaker, housewife/househusband","x":"어머니는 주부세요.","t":"My mother is a homemaker.","h":"주부세요 = is a homemaker (honorific 세요 for someone's mother/wife).","y":0,"u":1},{"k":"중국","e":"China","x":"왕웨이 씨는 중국 사람이에요.","t":"Wang Wei is Chinese.","h":"중국 사람 = Chinese person. Compare 중국어 (Chinese language, unit 18).","y":0,"u":1},{"k":"직업","e":"job, occupation","x":"직업이 뭐예요?","t":"What is your job?","h":"직업이 뭐예요? = What is your job? Formal question for forms and interviews.","y":0,"u":1},{"k":"초등학생","e":"elementary school student","x":"동생은 초등학생이에요.","t":"My younger sibling is an elementary school student.","h":"초등학교 (elementary school) + 생. Level 1 word chain: 초등학생 < 중학생 < 고등학생.","y":0,"u":1},{"k":"판매원","e":"salesperson","x":"언니는 백화점 판매원이에요.","t":"My sister is a salesperson at a department store.","h":"판매 (selling) + 원 (member) = salesperson. 백화점 판매원 = department store clerk.","y":0,"u":1},{"k":"필리핀","e":"the Philippines","x":"마리아 씨는 필리핀에서 왔어요.","t":"Maria came from the Philippines.","h":"Double ㅍ sound: pil-li-pin. 에서 왔어요 = came from.","y":0,"u":1},{"k":"학생","e":"student","x":"저는 대학생이에요. 학생이에요.","t":"I am a university student.","h":"생 = student/person suffix: 학생, 초등학생, 대학생 (university student).","y":0,"u":1},{"k":"한국","e":"Korea","x":"한국에 온 지 1년이에요.","t":"It has been a year since I came to Korea.","h":"한국어 = Korea + language. 한국 사람 = Korean person. 한국에 가요 = go to Korea.","y":0,"u":1},{"k":"한국어","e":"Korean language","x":"한국어를 공부해요.","t":"I study Korean.","h":"어 ending = language: 한국어, 영어, 중국어. Object particle: 한국어를 공부해요.","y":0,"u":1},{"k":"회사원","e":"company employee","x":"아버지는 회사원이에요.","t":"My father is a company employee.","h":"회사 (company) + 원 (member). Same pattern: 공장 직원, 은행원 (bank clerk).","y":0,"u":1},{"k":"거실","e":"living room","x":"거실에서 텔레비전을 봐요.","t":"I watch TV in the living room.","h":"Rooms of a home: 거실 (living room), 부엌 (kitchen), 화장실 (bathroom), 방 (room).","y":0,"u":2},{"k":"거울","e":"mirror","x":"거울을 봐요.","t":"I look in the mirror.","h":"거울을 보다 = look in the mirror. 을/를 = object particle.","y":0,"u":2},{"k":"교실","e":"classroom","x":"교실에 학생이 많아요.","t":"There are many students in the classroom.","h":"교실에 있어요 = is in the classroom. Location + 에 + 있다/없다.","y":0,"u":2},{"k":"그리고","e":"and, and then","x":"책상이 있어요. 그리고 의자도 있어요.","t":"There is a desk. And there is a chair too.","h":"Sentence starter: 그리고, ... = and then... Links sentences, not nouns (nouns use 하고/과).","y":0,"u":2},{"k":"기숙사","e":"dormitory","x":"기숙사에 살아요.","t":"I live in a dormitory.","h":"Dormitory. 기숙사에 살아요 = live in a dorm. 에 살다 = live in/at.","y":0,"u":2},{"k":"냉장고","e":"refrigerator","x":"냉장고 안에 우유가 있어요.","t":"There is milk in the fridge.","h":"냉장고 안에 = inside the fridge. Loanword-feel but pure Korean (cold-storage-box).","y":0,"u":2},{"k":"볼펜","e":"ballpoint pen","x":"볼펜으로 이름을 써요.","t":"I write my name with a pen.","h":"Instrument particle (으)로: 볼펜으로 써요 = write WITH a pen.","y":0,"u":2},{"k":"부엌","e":"kitchen","x":"부엌에서 요리해요.","t":"I cook in the kitchen.","h":"Also called 주방. 부엌에서 요리해요 = cook in the kitchen.","y":0,"u":2},{"k":"소파","e":"sofa","x":"소파에 앉아요.","t":"I sit on the sofa.","h":"Loanword (sofa). 소파에 앉아요 = sit on the sofa (에 앉다).","y":0,"u":2},{"k":"수건","e":"towel","x":"화장실에 수건이 있어요.","t":"There is a towel in the bathroom.","h":"수건이 있어요? = Is there a towel? Useful in goshiwon/hotel Korean.","y":0,"u":2},{"k":"시계","e":"clock, watch","x":"벽에 시계가 걸려 있어요.","t":"A clock is hanging on the wall.","h":"Confusable: 시계 = clock/watch, 시간 = time/hours. 벽에 걸려 있어요 = hangs on the wall.","y":0,"u":2},{"k":"식탁","e":"dining table","x":"식탁 위에 과일이 있어요.","t":"There is fruit on the dining table.","h":"식탁에 앉아요 = sit at the table. 식 = meal, 탁 = table.","y":0,"u":2},{"k":"에어컨","e":"air conditioner","x":"더워서 에어컨을 켜요.","t":"It is hot, so I turn on the air conditioner.","h":"Shortened from 에어컨디셔너. 에어컨을 켜요/꺼요 = turn on/off the AC.","y":0,"u":2},{"k":"옷장","e":"wardrobe","x":"옷장 안에 옷이 많아요.","t":"There are many clothes in the wardrobe.","h":"옷 (clothes) + 장 (cabinet). Same family: 신발장 (shoe cabinet).","y":0,"u":2},{"k":"의자","e":"chair","x":"책상 옆에 의자가 있어요.","t":"There is a chair next to the desk.","h":"옆에 = next to: 책상 옆에 의자가 있어요. Position words: 옆, 위, 아래, 앞, 뒤.","y":0,"u":2},{"k":"지도","e":"map","x":"벽에 한국 지도가 있어요.","t":"There is a map of Korea on the wall.","h":"Not to confuse with 지하철. 한국 지도 = map of Korea.","y":0,"u":2},{"k":"책","e":"book","x":"책상 위에 책이 있어요.","t":"There is a book on the desk.","h":"Count books with 권 (unit 8): 책 한 권. 위에 = on top of: 책상 위에 책.","y":0,"u":2},{"k":"책상","e":"desk","x":"방에 책상이 있어요.","t":"There is a desk in the room.","h":"방에 책상이 있어요: thing + 이/가 있어요 = there is. 책상이 (subject particle).","y":0,"u":2},{"k":"칠판","e":"blackboard","x":"선생님이 칠판에 써요.","t":"The teacher writes on the blackboard.","h":"칠판 앞에 = in front of the blackboard. Common classroom word with 보세요 (look).","y":0,"u":2},{"k":"침대","e":"bed","x":"방에 침대가 하나 있어요.","t":"There is one bed in the room.","h":"침대가 없어요 = there is no bed. 없어요 is the negative of 있어요.","y":0,"u":2},{"k":"컴퓨터","e":"computer","x":"침대 옆에 컴퓨터가 있어요.","t":"There is a computer next to the bed.","h":"Loanword, sounds like English. 컴퓨터가 있어요 / 없어요.","y":0,"u":2},{"k":"컵","e":"cup","x":"식탁 위에 컵이 있어요.","t":"There is a cup on the table.","h":"Counter for cups is 잔 (unit 8): 컵 한 잔 = one cup (of a drink).","y":0,"u":2},{"k":"필통","e":"pencil case","x":"필통 안에 볼펜이 있어요.","t":"There is a pen in the pencil case.","h":"안에 = inside: 필통 안에. 안 (inside) + 에 (location).","y":0,"u":2},{"k":"하지만","e":"but, however","x":"방이 작아요. 하지만 깨끗해요.","t":"The room is small. But it is clean.","h":"Sentence starter: 하지만, ... = but... For nouns inside a sentence use -지만 instead.","y":0,"u":2},{"k":"학교","e":"school","x":"학교에 가요.","t":"I go to school.","h":"학교에 가요 = go to school (에 = destination). 학교에서 공부해요 (에서 = where action happens).","y":0,"u":2},{"k":"화장실","e":"bathroom, restroom","x":"화장실이 어디예요?","t":"Where is the bathroom?","h":"화장실이 어디예요? = Where is the bathroom? Essential question.","y":0,"u":2},{"k":"회사","e":"company, office","x":"회사에서 일해요.","t":"I work at a company.","h":"회사에 다녀요 = go to work regularly (다니다 = attend/commute). 회사원 = office worker.","y":0,"u":2},{"k":"휴대 전화","e":"cell phone","x":"책상 위에 휴대 전화가 있어요.","t":"There is a cell phone on the desk.","h":"Also 핸드폰 (hand phone) in daily speech. Both are common.","y":0,"u":2},{"k":"휴지","e":"toilet paper, tissue","x":"휴지가 없어요.","t":"There is no toilet paper.","h":"휴지가 없어요 = there is no tissue/toilet paper. 없어요 = not exist.","y":0,"u":2},{"k":"고향 음식을 요리하다","e":"to cook hometown food","x":"주말에 고향 음식을 요리해요.","t":"I cook food from my hometown on the weekend.","h":"요리하다 = cook. 고향 = hometown. 요리를 잘해요 = cooks well (unit 10).","y":1,"u":3},{"k":"나쁘다","e":"to be bad","x":"이 음식은 나쁘지 않아요.","t":"This food is not bad.","h":"나빠요 (present, ㅡ irregular doubles ㅃ). Opposite of 좋다.","y":0,"u":3},{"k":"덥다","e":"to be hot (weather)","x":"여름에는 더워요.","t":"It is hot in summer.","h":"더워요 = hot (ㅂ irregular: ㅂ -> 우 -> 워). For weather. Opposite: 춥다 (추워요).","y":0,"u":3},{"k":"많다","e":"to be many, much","x":"사람이 많아요.","t":"There are many people.","h":"많아요 = many/much. With nouns use 많은: 많은 사람. 많이 = a lot (adverb).","y":0,"u":3},{"k":"맛없다","e":"to taste bad","x":"이 빵은 맛없어요.","t":"This bread tastes bad.","h":"맛없어요 = tastes bad. Pattern: 맛 + 없다 (taste does not exist).","y":0,"u":3},{"k":"맛있다","e":"to be delicious","x":"김치찌개가 맛있어요.","t":"The kimchi stew is delicious.","h":"맛있어요 = delicious. Literally taste-exists. Opposite: 맛없다 (맛없어요).","y":0,"u":3},{"k":"바쁘다","e":"to be busy","x":"요즘 바빠요.","t":"I am busy these days.","h":"바빠요 = busy (ㅡ irregular). 바빠서 못 가요 = busy so I cannot go.","y":0,"u":3},{"k":"방을 청소하다","e":"to clean the room","x":"토요일에 방을 청소해요.","t":"I clean my room on Saturday.","h":"청소하다 = clean. 방을 청소해요 = clean the room. Also 청소를 하다 (unit 9).","y":1,"u":3},{"k":"배가 고프다","e":"to be hungry","x":"배가 고파요. 밥을 먹어요.","t":"I am hungry. I eat rice.","h":"배 = stomach + 고프다 (hungry). 배고파요 = I am hungry. Opposite: 배부르다.","y":1,"u":3},{"k":"비싸다","e":"to be expensive","x":"이 가방은 비싸요.","t":"This bag is expensive.","h":"비싸요 = expensive (ㅡ irregular). Opposite: 싸다 (싸요 = cheap).","y":0,"u":3},{"k":"빵을 먹다","e":"to eat bread","x":"아침에 빵을 먹어요.","t":"I eat bread in the morning.","h":"먹다 = eat. 먹어요 (present). Opposite action: 요리하다 (cook).","y":1,"u":3},{"k":"쉽다","e":"to be easy","x":"이 문제는 쉬워요.","t":"This question is easy.","h":"쉬워요 = easy (ㅂ irregular). 한국어가 쉬워요? = Is Korean easy?","y":0,"u":3},{"k":"싸다","e":"to be cheap","x":"시장에서 싸게 사요.","t":"I buy it cheap at the market.","h":"싸요 = cheap. Careful with 사다 (buy) - 싸요 vs 사요 sound close.","y":0,"u":3},{"k":"아프다","e":"to hurt, be sick","x":"머리가 아파요.","t":"My head hurts.","h":"아파요 = hurt/sick. 배가 아파요 = stomach hurts (unit 16). Also 아파서 = because sick.","y":0,"u":3},{"k":"어렵다","e":"to be difficult","x":"한국어가 어려워요.","t":"Korean is difficult.","h":"어려워요 = difficult (ㅂ irregular). Opposite: 쉽다 (쉬워요).","y":0,"u":3},{"k":"예쁘다","e":"to be pretty","x":"꽃이 예뻐요.","t":"The flowers are pretty.","h":"예뻐요 = pretty (ㅡ irregular). 예쁜 꽃 = pretty flower.","y":0,"u":3},{"k":"옷을 사다","e":"to buy clothes","x":"백화점에서 옷을 사요.","t":"I buy clothes at the department store.","h":"사다 = buy. 사요. Do not confuse with 싸다 (to be cheap) - different vowel length feel.","y":1,"u":3},{"k":"운동하다","e":"to exercise","x":"공원에서 운동해요.","t":"I exercise in the park.","h":"하다-verb: noun 운동 (exercise) + 하다. Present 운동해요, past 운동했어요.","y":0,"u":3},{"k":"유튜브","e":"YouTube","x":"유튜브에서 한국어를 배워요.","t":"I learn Korean on YouTube.","h":"Loanword. 유튜브를 보다 = watch YouTube.","y":0,"u":3},{"k":"일하다","e":"to work","x":"회사에서 일해요.","t":"I work at a company.","h":"일 (work) + 하다. 일해요. Place + 에서 일해요 = work at.","y":0,"u":3},{"k":"자다","e":"to sleep","x":"밤에 일찍 자요.","t":"I sleep early at night.","h":"자다 = sleep. 자요 (present). Honorific: 주무시다 (unit 10).","y":0,"u":3},{"k":"작다","e":"to be small","x":"가방이 작아요.","t":"The bag is small.","h":"작아요 = small. Pair with 크다: 커요/작아요.","y":0,"u":3},{"k":"재미없다","e":"to be boring","x":"이 영화는 재미없어요.","t":"This movie is boring.","h":"재미없어요 = boring. 재미 + 없다. Pair with 재미있다.","y":0,"u":3},{"k":"재미있다","e":"to be fun, interesting","x":"한국 드라마가 재미있어요.","t":"Korean dramas are fun.","h":"재미있어요 = fun/interesting. 재미 + 있다. Very common exam word.","y":0,"u":3},{"k":"적다","e":"to be few, little","x":"오늘은 손님이 적어요.","t":"There are few customers today.","h":"적어요 = few/little. Opposite of 많다.","y":0,"u":3},{"k":"좋다","e":"to be good","x":"날씨가 좋아요.","t":"The weather is good.","h":"좋아요 (present). irregular: ㅎ drops. Opposite: 나쁘다.","y":0,"u":3},{"k":"책을 읽다","e":"to read a book","x":"자기 전에 책을 읽어요.","t":"I read a book before sleeping.","h":"읽다 has a tricky batchim: 읽어요 (il-geo-yo), 읽습니다. ㄺ reads as ㄱ before vowels here.","y":1,"u":3},{"k":"춥다","e":"to be cold (weather)","x":"겨울에는 추워요.","t":"It is cold in winter.","h":"추워요 = cold (ㅂ irregular). Weather only; for things use 차갑다.","y":0,"u":3},{"k":"친구를 만나다","e":"to meet a friend","x":"주말에 친구를 만나요.","t":"I meet my friend on the weekend.","h":"만나다 = meet. 만나요 (present). 친구를 만났어요 = met a friend (past, unit 9).","y":1,"u":3},{"k":"커피를 마시다","e":"to drink coffee","x":"아침에 커피를 마셔요.","t":"I drink coffee in the morning.","h":"마시다 = drink. 마셔요 (present). With nouns: 물을, 차를, 커피를 마시다.","y":1,"u":3},{"k":"크다","e":"to be big","x":"방이 커요.","t":"The room is big.","h":"커요 = big (ㅡ drops, ㅓ added). Opposite: 작다 (작아요).","y":0,"u":3},{"k":"텔레비전을 보다","e":"to watch TV","x":"저녁에 텔레비전을 봐요.","t":"I watch TV in the evening.","h":"보다 = see/watch. 봐요 (present): 텔레비전을 봐요.","y":1,"u":3},{"k":"학생들","e":"students (plural)","x":"학생들이 교실에 있어요.","t":"The students are in the classroom.","h":"들 = plural marker: 학생들, 사람들. Often optional in Korean.","y":0,"u":3},{"k":"한국어를 공부하다","e":"to study Korean","x":"도서관에서 한국어를 공부해요.","t":"I study Korean at the library.","h":"공부하다 = study. Object + 를 + 공부하다. Present: 공부해요.","y":1,"u":3},{"k":"PC방","e":"internet cafe","x":"PC방에서 게임을 해요.","t":"I play games at a PC bang.","h":"PC + 방 (room) = internet cafe. 피씨방 in speech. Pays per hour.","y":0,"u":4},{"k":"공원","e":"park","x":"공원에서 산책해요.","t":"I take a walk in the park.","h":"공원에서 산책해요 = walk in the park. 에서 for the action place.","y":0,"u":4},{"k":"극장","e":"movie theater","x":"극장에서 영화를 봐요.","t":"I watch a movie at the theater.","h":"영화를 보러 극장에 가요. Nearly same as 영화관; 극장 also means theater (plays).","y":0,"u":4},{"k":"근처","e":"vicinity, nearby area","x":"집 근처에 마트가 있어요.","t":"There is a mart near my house.","h":"근처에 있어요 = it is nearby. 집 근처 = near home. Compare 가깝다 (to be near).","y":0,"u":4},{"k":"기타","e":"guitar","x":"공원에서 기타를 쳐요.","t":"I play guitar in the park.","h":"Loanword (guitar). 기타를 치다 = play the guitar (치다 = strike/play strings).","y":0,"u":4},{"k":"남편","e":"husband","x":"남편하고 시장에 가요.","t":"I go to the market with my husband.","h":"Husband. Wife = 아내. Formal: 남편분. Compare 남자친구 (boyfriend).","y":0,"u":4},{"k":"노래방","e":"karaoke room","x":"친구하고 노래방에 가요.","t":"I go to a karaoke room with my friend.","h":"노래 (song) + 방 (room) = karaoke room. 방 pattern: PC방, 찜질방, 빨래방.","y":0,"u":4},{"k":"마트","e":"supermarket, mart","x":"마트에서 과일을 사요.","t":"I buy fruit at the mart.","h":"From English mart. 마트에 가요 = go to the mart. Bigger than 편의점.","y":0,"u":4},{"k":"문화 센터","e":"culture center","x":"문화 센터에서 한국 요리를 배워요.","t":"I learn Korean cooking at the culture center.","h":"센터 = center. Classes there: 한국 요리를 배워요 (unit 12).","y":0,"u":4},{"k":"미용실","e":"hair salon","x":"미용실에서 머리를 잘라요.","t":"I get a haircut at the salon.","h":"미용 (beauty) + 실 (room) = hair salon. 실 pattern: 탈의실 (fitting room).","y":0,"u":4},{"k":"밖","e":"outside","x":"밖에서 기다려요.","t":"I wait outside.","h":"Outside. Opposite: 안 (inside, unit 2 필통 안에). 밖에 나가요 = go outside.","y":0,"u":4},{"k":"배우다","e":"to learn","x":"한국어를 배워요.","t":"I learn Korean.","h":"배워요 = learn. 배우다 vs 공부하다: 배우다 = learn a skill, 공부하다 = study.","y":0,"u":4},{"k":"백화점","e":"department store","x":"백화점에서 옷을 사요.","t":"I buy clothes at the department store.","h":"백화 (hundred goods) + 점 (store) = department store. Hyundai, Lotte, Shinsegae.","y":0,"u":4},{"k":"병원","e":"hospital","x":"아파서 병원에 가요.","t":"I am sick, so I go to the hospital.","h":"아파서 병원에 가요 = sick so I go to the hospital (unit 16 links here).","y":0,"u":4},{"k":"빨래방","e":"laundromat","x":"빨래방에서 빨래를 해요.","t":"I do laundry at the laundromat.","h":"빨래 (laundry) + 방 (room) = laundromat. 빨래를 하다 = do laundry (unit 9).","y":0,"u":4},{"k":"서점","e":"bookstore","x":"서점에서 한국어 책을 사요.","t":"I buy a Korean book at the bookstore.","h":"서 (book) + 점 (store) = bookstore. 서점에서 책을 사요.","y":0,"u":4},{"k":"시장","e":"market","x":"시장에서 채소를 사요.","t":"I buy vegetables at the market.","h":"Traditional market. 시장에서 사요 = buy at the market. Compare 마트 (modern store).","y":0,"u":4},{"k":"식당","e":"restaurant","x":"라흐만 씨가 식당에 가요.","t":"Rahman goes to a restaurant.","h":"식당에 가요 = go to a restaurant. 집 suffix for kinds: 한식집, 중국집 (unit 7).","y":0,"u":4},{"k":"아주","e":"very","x":"이 책이 아주 재미있어요.","t":"This book is very interesting.","h":"아주 좋아요 = very good. Same meaning as 매우, 정말, 진짜.","y":0,"u":4},{"k":"약국","e":"pharmacy","x":"약국에서 약을 사요.","t":"I buy medicine at the pharmacy.","h":"약 (medicine) + 국 (shop). 약국에서 약을 사요 = buy medicine at the pharmacy.","y":0,"u":4},{"k":"영화관","e":"cinema","x":"영화관이 어디예요?","t":"Where is the cinema?","h":"영화 (movie) + 관 (hall). 영화관에서 영화를 봐요.","y":0,"u":4},{"k":"우체국","e":"post office","x":"우체국에서 소포를 보내요.","t":"I send a package at the post office.","h":"우체 (mail) + 국 (office) = post office. 소포 (parcel) goes here (unit 13).","y":0,"u":4},{"k":"은행","e":"bank","x":"은행에서 돈을 찾아요.","t":"I withdraw money at the bank.","h":"은행에서 환전해요 = exchange money at the bank (unit 13).","y":0,"u":4},{"k":"주말","e":"weekend","x":"주말에 친구를 만나요.","t":"I meet my friend on the weekend.","h":"주말에 뭐 해요? = What do you do on the weekend? Opposite: 평일 (weekday, unit 18).","y":0,"u":4},{"k":"직원 식당","e":"staff cafeteria","x":"직원 식당에서 점심을 먹어요.","t":"I eat lunch at the staff cafeteria.","h":"직원 (staff) + 식당 = staff cafeteria. Same as 회사 식당 below.","y":0,"u":4},{"k":"집","e":"house, home","x":"집에서 쉬어요.","t":"I rest at home.","h":"집에 가요 = go home. 집에서 쉬어요 = rest at home. 에 가요 vs 에서 있어요.","y":0,"u":4},{"k":"찜질방","e":"Korean sauna","x":"찜질방에서 쉬어요.","t":"I rest at the sauna.","h":"Korean sauna with heated rooms. 찜질 = steaming. Part of the 방 family.","y":0,"u":4},{"k":"카페","e":"cafe","x":"카페에서 커피를 마셔요.","t":"I drink coffee at a cafe.","h":"카페에서 커피를 마셔요. 에서 = place where the action happens.","y":0,"u":4},{"k":"편의점","e":"convenience store","x":"편의점에서 김밥을 사요.","t":"I buy gimbap at the convenience store.","h":"편의 (convenience) + 점 (store). GS25, CU are 편의점.","y":0,"u":4},{"k":"학교","e":"school","x":"학교 앞에서 만나요.","t":"Let's meet in front of the school.","h":"학교에 가요 = go to school (에 = destination). 학교에서 공부해요 (에서 = where action happens).","y":0,"u":4},{"k":"헬스장","e":"gym","x":"헬스장에서 운동해요.","t":"I exercise at the gym.","h":"From English health + 장 (place) = gym. 헬스장에서 운동해요.","y":0,"u":4},{"k":"회사","e":"company, office","x":"회사가 집에서 멀어요.","t":"The office is far from home.","h":"회사에 다녀요 = go to work regularly (다니다 = attend/commute). 회사원 = office worker.","y":0,"u":4},{"k":"회사 식당","e":"company cafeteria","x":"회사 식당이 1층에 있어요.","t":"The company cafeteria is on the first floor.","h":"회사 (company) + 식당 = company cafeteria. Noun + noun compound.","y":0,"u":4},{"k":"공","e":"zero (Sino-Korean)","x":"010에서 공이라고 읽어요.","t":"In 010 you read it as \"gong\" / zero.","h":"Sino-Korean zero, used in phone numbers: 010-XXXX-XXXX reads 공일공. Compare 영.","y":0,"u":5},{"k":"구","e":"nine (Sino-Korean)","x":"9시에 수업이 시작해요.","t":"Class starts at 9.","h":"Sino number 9. 9월 = September. Counts with 층: 9층 = 9th floor.","y":0,"u":5},{"k":"금요일","e":"Friday","x":"금요일 저녁에 회식이 있어요.","t":"There is a company dinner on Friday evening.","h":"금 = metal/gold. Friday. 불금 = burning Friday (slang for Friday night).","y":0,"u":5},{"k":"내일","e":"tomorrow","x":"내일 시험이 있어요.","t":"I have a test tomorrow.","h":"Tomorrow. With future: 내일 만날 거예요. Chain: 어제, 오늘, 내일.","y":0,"u":5},{"k":"다음 주","e":"next week","x":"다음 주에 시험이 있어요.","t":"I have a test next week.","h":"다음 = next. 다음 주에 가요 = go next week.","y":0,"u":5},{"k":"며칠","e":"what date; a few days","x":"오늘이 며칠이에요?","t":"What is the date today?","h":"Two meanings: WHAT date (며칠이에요? = what is the date?) and a FEW days.","y":0,"u":5},{"k":"명함","e":"business card","x":"명함을 주고받아요.","t":"We exchange business cards.","h":"명 (name) + 함 (card case) = business card. 명함을 주다/받다 = give/receive.","y":0,"u":5},{"k":"몇 월","e":"what month","x":"지금 몇 월이에요?","t":"What month is it now?","h":"몇 = what/how many + 월 = month. 몇 월 며칠이에요? = What month and date?","y":0,"u":5},{"k":"목요일","e":"Thursday","x":"목요일에 운동해요.","t":"I exercise on Thursday.","h":"목 = tree. Thursday.","y":0,"u":5},{"k":"빌딩","e":"building","x":"빌딩 앞에서 만나요.","t":"Let's meet in front of the building.","h":"Loanword (building). 빌딩에서 일해요 = work in a building.","y":0,"u":5},{"k":"사","e":"four (Sino-Korean)","x":"4층에서 일해요.","t":"I work on the fourth floor.","h":"Sino number 4. 4 is unlucky in Korea (사 = death sound); some buildings skip 4층.","y":0,"u":5},{"k":"삼","e":"three (Sino-Korean)","x":"3월에 봄이 와요.","t":"Spring comes in March.","h":"Sino number 3. 삼성 = Samsung (three stars).","y":0,"u":5},{"k":"삼십","e":"thirty (Sino-Korean)","x":"30일에 만나요.","t":"Let's meet on the 30th.","h":"Sino 30. Months have up to 삼십일 일 (31st).","y":0,"u":5},{"k":"수요일","e":"Wednesday","x":"수요일에 친구를 만나요.","t":"I meet my friend on Wednesday.","h":"수 = water. Wednesday.","y":0,"u":5},{"k":"십","e":"ten (Sino-Korean)","x":"10월에 단풍이 예뻐요.","t":"The autumn leaves are pretty in October.","h":"Sino 10. Build numbers: 십일 = 11, 이십 = 20, 삼십오 = 35.","y":0,"u":5},{"k":"어제","e":"yesterday","x":"어제 친구를 만났어요.","t":"I met my friend yesterday.","h":"Yesterday. With past tense: 어제 만났어요 = met yesterday.","y":0,"u":5},{"k":"영","e":"zero","x":"전화번호에 영이 있어요.","t":"There is a zero in the phone number.","h":"Native-style zero for scores/math: 0점 = 영점. Phone numbers use 공 instead.","y":0,"u":5},{"k":"오","e":"five (Sino-Korean)","x":"오늘은 5월 5일이에요.","t":"Today is May 5th.","h":"Sino number 5. 오월 = May. 어린이날 = 5월 5일 (unit 11).","y":0,"u":5},{"k":"오늘","e":"today","x":"오늘은 5월 5일이에요.","t":"Today is May 5th.","h":"오늘은 5월 5일이에요. 은/는 topic particle after 오늘. Sequence: 어제 - 오늘 - 내일.","y":0,"u":5},{"k":"요일","e":"day of the week","x":"오늘은 무슨 요일이에요?","t":"What day of the week is it today?","h":"요일 = day of week. Days end in 요일: 월요일...일요일. 무슨 요일이에요? = What day is it?","y":0,"u":5},{"k":"월요일","e":"Monday","x":"월요일에 회의가 있어요.","t":"There is a meeting on Monday.","h":"월 = moon/Monday. Days: 월화수목금토일 + 요일. Memorize the order as one word.","y":0,"u":5},{"k":"육","e":"six (Sino-Korean)","x":"6시에 퇴근해요.","t":"I leave work at 6 o'clock.","h":"Sino number 6. Pronounced 육, but 6월 reads 유월 (special rule).","y":0,"u":5},{"k":"의사","e":"doctor","x":"의사 선생님이 친절해요.","t":"The doctor is kind.","h":"Doctor. 의사 선생님 = doctor (polite). Compare 간호사 (nurse). At 병원.","y":0,"u":5},{"k":"이","e":"two (Sino-Korean)","x":"2월에 추워요.","t":"It is cold in February.","h":"Tooth. 이가 아파요 = toothache -> 치과. Homonym: 이 = Sino number 2 (unit 5).","y":0,"u":5},{"k":"이번 주","e":"this week","x":"이번 주에 바빠요.","t":"I am busy this week.","h":"이번 = this + 주 = week. Pattern: 이번 주, 다음 주, 지난주.","y":0,"u":5},{"k":"이십","e":"twenty (Sino-Korean)","x":"20일에 휴가를 가요.","t":"I go on vacation on the 20th.","h":"Sino 20 = 이 + 십 (two tens). 30 = 삼십. Dates: 20일 = 이십 일.","y":0,"u":5},{"k":"일","e":"one (Sino-Korean)","x":"1층에 가요.","t":"I go to the first floor.","h":"Sino number 1. Sino set: 일이삼사오육칠팔구십. Used for dates, money, floors, minutes.","y":0,"u":5},{"k":"일요일","e":"Sunday","x":"일요일에 교회에 가요.","t":"I go to church on Sunday.","h":"일 = sun. Sunday. Note: 일요일 (day) vs 일 (number one) - same character, different word.","y":0,"u":5},{"k":"지난주","e":"last week","x":"지난주에 고향 친구를 만났어요.","t":"I met a friend from home last week.","h":"지난 = last/past. 지난 주말에 = last weekend (unit 9).","y":0,"u":5},{"k":"층","e":"floor, story","x":"사무실이 3층에 있어요.","t":"The office is on the 3rd floor.","h":"Floor counter: 1층, 2층. 몇 층이에요? = Which floor? 위층/아래층 = up/downstairs (unit 17).","y":0,"u":5},{"k":"칠","e":"seven (Sino-Korean)","x":"7월에 더워요.","t":"It is hot in July.","h":"Sino number 7. 7월 = July = 칠월.","y":0,"u":5},{"k":"토요일","e":"Saturday","x":"토요일에 쉬어요.","t":"I rest on Saturday.","h":"토 = earth. Saturday. Weekend: 토요일 + 일요일 = 주말.","y":0,"u":5},{"k":"팔","e":"eight (Sino-Korean)","x":"8시에 아침을 먹어요.","t":"I eat breakfast at 8 o'clock.","h":"Arm. Homonym: 팔 = Sino number 8 (unit 5). 팔이 아파요 = my arm hurts.","y":0,"u":5},{"k":"호","e":"room number (counter)","x":"507호에서 살아요.","t":"I live in room 507.","h":"Room/apartment number counter: 101호 = room 101. Read with Sino numbers.","y":0,"u":5},{"k":"화요일","e":"Tuesday","x":"화요일에 한국어 수업이 있어요.","t":"I have Korean class on Tuesday.","h":"화 = fire. 월화수목금토일 = moon fire water tree metal earth sun.","y":0,"u":5},{"k":"낮","e":"daytime","x":"낮에 일해요.","t":"I work during the day.","h":"Daytime. Opposite: 밤 (night). 낮에 일해요 = work in the day.","y":0,"u":6},{"k":"넷","e":"four (native Korean)","x":"우리 가족은 넷이에요.","t":"My family is four people.","h":"Native 4. Before counters: 네 개, 네 명, 네 장.","y":0,"u":6},{"k":"다섯","e":"five (native Korean)","x":"다섯 시에 만나요.","t":"Let's meet at five.","h":"Native 5. Stays as is before counters: 다섯 개.","y":0,"u":6},{"k":"둘","e":"two (native Korean)","x":"커피 둘 주세요.","t":"Two coffees, please.","h":"Native 2. Before counters: 두 개, 두 명, 두 잔 (둘 loses ㄹ).","y":0,"u":6},{"k":"마흔","e":"forty (native Korean)","x":"아버지는 마흔여덟 살이세요.","t":"My father is forty-eight.","h":"Native 40. Decades: 서른, 마흔, 쉰, 예순, 일흔, 여든, 아흔.","y":0,"u":6},{"k":"반","e":"half (past the hour)","x":"두 시 반에 만나요.","t":"Let's meet at 2:30.","h":"Half past: 9시 반 = 9:30. Easier than saying 삼십 분.","y":0,"u":6},{"k":"밤","e":"night","x":"밤에 일찍 자요.","t":"I go to bed early at night.","h":"Night. 밤에 자요 = sleep at night. 밤 11시 = 11pm.","y":0,"u":6},{"k":"분","e":"minute","x":"5분만 기다려요.","t":"Wait just five minutes.","h":"Honorific counter for people: 두 분 = two people (respected). Plain version: 명 (unit 8).","y":0,"u":6},{"k":"새벽","e":"dawn, early morning","x":"새벽에 일어나요.","t":"I wake up at dawn.","h":"Dawn, roughly 3-6am. Day chain: 새벽 - 아침 - 낮 - 저녁 - 밤.","y":0,"u":6},{"k":"서른","e":"thirty (native Korean)","x":"형은 서른 살이에요.","t":"My older brother is thirty.","h":"Native 30. 서른 살 = 30 years old. Ages use native numbers.","y":0,"u":6},{"k":"세수하다","e":"to wash one's face","x":"일어나서 세수해요.","t":"I get up and wash my face.","h":"세수해요 = wash face. Morning routine: 일어나다 - 세수하다 - 옷을 입다 - 출근하다.","y":0,"u":6},{"k":"셋","e":"three (native Korean)","x":"사람이 셋이에요.","t":"There are three people.","h":"Native 3. Before counters: 세 개, 세 명, 세 병.","y":0,"u":6},{"k":"쉰","e":"fifty (native Korean)","x":"어머니는 쉰 살이세요.","t":"My mother is fifty.","h":"Native 50. 쉰 살 = 50 years old.","y":0,"u":6},{"k":"스물","e":"twenty (native Korean)","x":"저는 스물 살이에요.","t":"I am twenty years old.","h":"Native 20. 스무 살 = 20 years old (스물 -> 스무 before counter).","y":0,"u":6},{"k":"시","e":"o'clock","x":"지금 몇 시예요?","t":"What time is it now?","h":"O'clock counter with NATIVE numbers: 한 시, 두 시, 세 시. 9시 = 아홉 시.","y":0,"u":6},{"k":"아침","e":"morning; breakfast","x":"아침을 먹어요.","t":"I eat breakfast.","h":"Morning AND breakfast: 아침을 먹어요 = eat breakfast. Same for 점심, 저녁.","y":0,"u":6},{"k":"아홉","e":"nine (native Korean)","x":"아홉 시부터 일해요.","t":"I work from nine.","h":"Native 9. 아홉 시 = 9 o'clock.","y":0,"u":6},{"k":"아흔","e":"ninety (native Korean)","x":"시험에서 아흔 점을 받았어요.","t":"I got ninety points on the test.","h":"Native 90. 아흔 살. 99 = 아흔아홉.","y":0,"u":6},{"k":"여덟","e":"eight (native Korean)","x":"여덟 시에 출근해요.","t":"I go to work at eight.","h":"Native 8. Final ㅄ silent before consonants: 여덟 시 reads 여덟씨 -> 여덜시.","y":0,"u":6},{"k":"여든","e":"eighty (native Korean)","x":"이 건물은 여든 층이에요.","t":"This building has eighty floors.","h":"Native 80. 여든 살.","y":0,"u":6},{"k":"여섯","e":"six (native Korean)","x":"여섯 시에 일어나요.","t":"I get up at six.","h":"Native 6. 여섯 시 = 6 o'clock. Hours use native numbers!","y":0,"u":6},{"k":"열","e":"ten (native Korean)","x":"열 시에 수업이 끝나요.","t":"Class ends at ten.","h":"Native 10. 열 시 = 10 o'clock. 열하나 = 11.","y":0,"u":6},{"k":"열둘","e":"twelve (native Korean)","x":"열둘 시에 점심을 먹어요.","t":"I eat lunch at twelve.","h":"Native 12. 열 + 둘. 열두 시 = 12 o'clock (둘 -> 두 before counter).","y":0,"u":6},{"k":"열하나","e":"eleven (native Korean)","x":"열하나 시에 자요.","t":"I sleep at eleven.","h":"Native 11. 열 + 하나. 12 = 열둘. Used for hours 11, 12.","y":0,"u":6},{"k":"예순","e":"sixty (native Korean)","x":"할아버지는 예순 살이세요.","t":"My grandfather is sixty.","h":"Native 60. 예순 살. After 60 Koreans often switch to Sino numbers.","y":0,"u":6},{"k":"오전","e":"a.m., morning","x":"오전 9시에 수업이 시작해요.","t":"Class starts at 9 a.m.","h":"a.m. 오전 9시 = 9am. Pair: 오전/오후 instead of am/pm.","y":0,"u":6},{"k":"오후","e":"p.m., afternoon","x":"오후 6시에 퇴근해요.","t":"I leave work at 6 p.m.","h":"p.m. 오후 6시 = 6pm. 오전 = before noon, 오후 = after noon.","y":0,"u":6},{"k":"옷을 입다","e":"to put on clothes","x":"아침에 옷을 입어요.","t":"I put on clothes in the morning.","h":"입다 = put on (clothes). 입어요. Opposite: 벗다 (take off).","y":1,"u":6},{"k":"일곱","e":"seven (native Korean)","x":"일곱 시에 아침을 먹어요.","t":"I eat breakfast at seven.","h":"Native 7. 일곱 시 = 7 o'clock.","y":0,"u":6},{"k":"일어나다","e":"to get up","x":"아침 7시에 일어나요.","t":"I get up at 7 in the morning.","h":"일어나요 = get up. 7시에 일어나요 = get up at 7. Opposite: 자다.","y":0,"u":6},{"k":"일흔","e":"seventy (native Korean)","x":"할머니는 일흔 살이세요.","t":"My grandmother is seventy.","h":"Native 70. 일흔 살.","y":0,"u":6},{"k":"잠을 자다","e":"to sleep","x":"밤 11시에 잠을 자요.","t":"I sleep at 11 p.m.","h":"잠 (sleep) + 자다 = to sleep. Same as 자다, more explicit. 잠을 자요.","y":1,"u":6},{"k":"저녁","e":"evening; dinner","x":"저녁 7시에 만날까요?","t":"Shall we meet at 7 in the evening?","h":"Evening AND dinner: 저녁을 먹어요 = eat dinner (unit 9). 저녁 7시 = 7pm.","y":0,"u":6},{"k":"출근하다","e":"to go to work","x":"9시에 출근해요.","t":"I go to work at 9.","h":"출근해요 = go to work. 출 (leave) + 근 (work). Opposite: 퇴근하다.","y":0,"u":6},{"k":"테니스","e":"tennis","x":"주말에 테니스를 쳐요.","t":"I play tennis on the weekend.","h":"Loanword. 테니스를 치다 = play tennis (치다 for racket sports).","y":0,"u":6},{"k":"퇴근하다","e":"to leave work","x":"6시에 퇴근해요.","t":"I leave work at 6.","h":"퇴근해요 = leave work. 6시에 퇴근해요. Pair with 출근하다.","y":0,"u":6},{"k":"하나","e":"one (native Korean)","x":"김밥 하나 주세요.","t":"One gimbap, please.","h":"Native number 1. Before counters it shortens: 한 개, 한 명, 한 잔. Use for counting things.","y":0,"u":6},{"k":"한국어를 배우다","e":"to learn Korean","x":"학원에서 한국어를 배워요.","t":"I learn Korean at an academy.","h":"배워요 = learn. 배우다 vs 공부하다: 배우다 = learn (skill), 공부하다 = study.","y":1,"u":6},{"k":"그릇","e":"bowl, dish (counter)","x":"밥 두 그릇 주세요.","t":"Two bowls of rice, please.","h":"Counter for bowls of food: 비빔밥 한 그릇 = one bowl of bibimbap.","y":0,"u":7},{"k":"기다리다","e":"to wait","x":"음식을 기다려요.","t":"I wait for the food.","h":"기다려요 = wait. 잠깐 기다려 주세요 = please wait a moment.","y":0,"u":7},{"k":"김밥","e":"gimbap (seaweed rice roll)","x":"김밥 하나 주세요.","t":"One gimbap, please.","h":"김 (seaweed) + 밥 (rice). Cheap snack food, sold at 분식집.","y":0,"u":7},{"k":"김치찌개","e":"kimchi stew","x":"김치찌개 하나 주세요.","t":"One kimchi stew, please.","h":"김치 + 찌개 (stew). 찌개 family: 김치찌개, 된장찌개. Eaten shared, boiling hot.","y":0,"u":7},{"k":"돈가스","e":"pork cutlet","x":"돈가스 하나 주세요.","t":"One pork cutlet, please.","h":"From Japanese tonkatsu. Pork cutlet with sauce. Also 치즈돈가스.","y":0,"u":7},{"k":"된장찌개","e":"soybean paste stew","x":"된장찌개가 맛있어요.","t":"The soybean paste stew is delicious.","h":"된장 = soybean paste. 된장찌개 하나 주세요 = one doenjang stew please.","y":0,"u":7},{"k":"떡볶이","e":"tteokbokki (spicy rice cakes)","x":"떡볶이가 매워요.","t":"The tteokbokki is spicy.","h":"떡 (rice cake) + 볶이 (stir-fried). Spicy street food. 분식집 classic.","y":0,"u":7},{"k":"라면","e":"ramyeon (instant noodles)","x":"라면을 끓여요.","t":"I cook ramyeon.","h":"Instant noodles. Korean ramen, spicier than Japanese 라멘. 편의점 staple.","y":0,"u":7},{"k":"만두","e":"dumplings","x":"만두를 좋아해요.","t":"I like dumplings.","h":"Dumplings. 만두국 = dumpling soup. Steam: 찐만두.","y":0,"u":7},{"k":"메뉴","e":"menu","x":"메뉴 좀 주세요.","t":"The menu, please.","h":"Loanword. 메뉴 주세요 = menu please. 메뉴판 = menu board.","y":0,"u":7},{"k":"물 좀 주다","e":"to give some water","x":"물 좀 주세요.","t":"Some water, please.","h":"물 좀 주세요 = some water please. 좀 softens the request. Very useful pattern.","y":1,"u":7},{"k":"반찬","e":"side dishes","x":"반찬이 많아요.","t":"There are many side dishes.","h":"Side dishes that come free with a meal. 반찬 좀 더 주세요 = more side dishes please.","y":0,"u":7},{"k":"반찬 좀 더 주다","e":"to give more side dishes","x":"반찬 좀 더 주세요.","t":"More side dishes, please.","h":"좀 = a little/please (softener). ...좀 주세요 = polite casual request. 더 = more.","y":1,"u":7},{"k":"분식집","e":"snack bar (Korean casual eatery)","x":"분식집에서 김밥을 사요.","t":"I buy gimbap at a snack bar.","h":"분식 = flour-based snacks. Cheap casual eatery: 김밥, 떡볶이, 라면, 순대.","y":0,"u":7},{"k":"불고기","e":"bulgogi (marinated beef)","x":"불고기 3인분 주세요.","t":"Three servings of bulgogi, please.","h":"불 (fire) + 고기 (meat) = marinated grilled beef. 고기 family: 불고기, 삼겹살.","y":0,"u":7},{"k":"불고기 3인분 주다","e":"to give three servings of bulgogi","x":"불고기 3인분 주세요.","t":"Three servings of bulgogi, please.","h":"인분 = counter for servings: 1인분, 2인분. Sino numbers: 3인분 = 삼 인분.","y":1,"u":7},{"k":"비빔밥","e":"bibimbap (mixed rice)","x":"비빔밥을 비벼서 먹어요.","t":"I mix and eat the bibimbap.","h":"비빔 (mixing) + 밥 (rice). Mix it before eating. 전주 비빔밥 is famous (unit 9).","y":0,"u":7},{"k":"삼겹살","e":"pork belly","x":"삼겹살을 구워요.","t":"We grill pork belly.","h":"삼겹 (three layers) + 살 (flesh) = pork belly. Grilled at the table, wrapped in lettuce.","y":0,"u":7},{"k":"삼계탕","e":"ginseng chicken soup","x":"여름에 삼계탕을 먹어요.","t":"We eat ginseng chicken soup in summer.","h":"삼계 (ginseng chicken) + 탕 (soup). Whole young chicken, summer stamina food.","y":0,"u":7},{"k":"샐러드","e":"salad","x":"샐러드하고 스파게티를 주세요.","t":"Salad and spaghetti, please.","h":"Loanword (salad). 샐러드를 먹어요.","y":0,"u":7},{"k":"생선회","e":"raw fish, sashimi","x":"생선회를 좋아해요.","t":"I like raw fish.","h":"생선 (fish) + 회 (raw slices) = sashimi. 회 pattern: 초밥 (sushi).","y":0,"u":7},{"k":"순대","e":"sundae (Korean blood sausage)","x":"분식집에서 순대를 먹어요.","t":"I eat sundae at a snack bar.","h":"Blood sausage with noodles inside. Not the dessert sundae! 분식집 food.","y":0,"u":7},{"k":"숟가락","e":"spoon","x":"숟가락하고 젓가락 주세요.","t":"A spoon and chopsticks, please.","h":"Spoon. Koreans eat rice with 숟가락, side dishes with 젓가락.","y":0,"u":7},{"k":"스파게티","e":"spaghetti","x":"이탈리아 식당에서 스파게티를 먹어요.","t":"I eat spaghetti at an Italian restaurant.","h":"Loanword. 이탈리아 식당 food with 피자.","y":0,"u":7},{"k":"우동","e":"udon noodles","x":"우동이 뜨거워요.","t":"The udon is hot.","h":"Udon noodles, from Japanese. Hot noodle soup.","y":0,"u":7},{"k":"이름을 쓰다","e":"to write one's name","x":"여기에 이름을 쓰세요.","t":"Write your name here.","h":"쓰다 = write. 써요. Also use 쓰다 for: 카드를 쓰다 (unit 11).","y":1,"u":7},{"k":"이탈리아 식당","e":"Italian restaurant","x":"이탈리아 식당에서 피자를 먹어요.","t":"I eat pizza at an Italian restaurant.","h":"Italian restaurant. Sells 스파게티, 피자. 식당 = restaurant (unit 4).","y":0,"u":7},{"k":"일식집","e":"Japanese restaurant","x":"일식집에서 회식을 해요.","t":"We have a company dinner at a Japanese restaurant.","h":"Japanese restaurant. Sells 초밥, 우동, 돈가스.","y":0,"u":7},{"k":"젓가락","e":"chopsticks","x":"젓가락으로 먹어요.","t":"I eat with chopsticks.","h":"Chopsticks. Pair: 숟가락 (spoon). Korean set = 수저 (spoon + chopsticks).","y":0,"u":7},{"k":"주문하다","e":"to order (food)","x":"음식을 주문해요.","t":"I order food.","h":"주문해요 = order. 주문하시겠어요? = Would you like to order? (staff asks).","y":0,"u":7},{"k":"중국집","e":"Chinese restaurant","x":"중국집에서 짜장면을 시켜요.","t":"I order jjajangmyeon at a Chinese restaurant.","h":"Chinese restaurant. Sells 짜장면, 짬뽕, 탕수육. Delivers.","y":0,"u":7},{"k":"짜장면","e":"jjajangmyeon (black bean noodles)","x":"중국집에서 짜장면을 먹어요.","t":"I eat jjajangmyeon at a Chinese restaurant.","h":"Black bean sauce noodles. From 중국집 (Chinese restaurant). Pair: 짬뽕.","y":0,"u":7},{"k":"짬뽕","e":"jjamppong (spicy seafood noodles)","x":"짬뽕이 조금 매워요.","t":"The jjamppong is a little spicy.","h":"Spicy seafood noodle soup. The classic choice question: 짜장면이요, 짬뽕이요?","y":0,"u":7},{"k":"초밥","e":"sushi","x":"일식집에서 초밥을 먹어요.","t":"I eat sushi at a Japanese restaurant.","h":"Sushi (vinegared rice + fish). Compare 생선회: 초밥 has rice.","y":0,"u":7},{"k":"탕수육","e":"sweet and sour pork","x":"탕수육을 시켜요.","t":"We order sweet and sour pork.","h":"Sweet and sour pork. 중국집 dish, ordered together with 짜장면.","y":0,"u":7},{"k":"피자","e":"pizza","x":"친구하고 피자를 먹어요.","t":"I eat pizza with my friend.","h":"Loanword. 피자를 시키다 = order pizza (delivery).","y":0,"u":7},{"k":"한식집","e":"Korean restaurant","x":"한식집에서 점심을 먹어요.","t":"I eat lunch at a Korean restaurant.","h":"한식 (Korean food) + 집 (house/shop). Pattern: 중국집, 일식집.","y":0,"u":7},{"k":"햄버거","e":"hamburger","x":"점심에 햄버거를 먹어요.","t":"I eat a hamburger for lunch.","h":"Loanword. 햄버거 하나 주세요 = one hamburger please.","y":0,"u":7},{"k":"강아지","e":"puppy","x":"강아지가 귀여워요.","t":"The puppy is cute.","h":"Puppy/dog (cute word). Count: 강아지 한 마리. Compare 개 (dog, plain).","y":0,"u":8},{"k":"개","e":"counter for animals/pets (also: dog)","x":"개가 두 마리 있어요.","t":"I have two dogs.","h":"Two meanings: DOG, and the general counter for THINGS (개). 사과 두 개 = two apples.","y":0,"u":8},{"k":"계란","e":"egg","x":"계란 한 판 주세요.","t":"One carton of eggs, please.","h":"Egg. Also 달걀 in pure Korean. 계란 두 개 = two eggs.","y":0,"u":8},{"k":"권","e":"counter for books","x":"책 다섯 권을 읽어요.","t":"I read five books.","h":"Counter for books: 책 한 권, 잡지 두 권. Native numbers: 한 권, 두 권.","y":0,"u":8},{"k":"노트북","e":"laptop","x":"노트북을 사고 싶어요.","t":"I want to buy a laptop.","h":"Loanword: notebook = laptop in Korean. Desktop = 데스크톱.","y":0,"u":8},{"k":"녹차","e":"green tea","x":"녹차를 마셔요.","t":"I drink green tea.","h":"녹 (green) + 차 (tea). 차 family: 녹차, 인삼차 (unit 12), 생강차 (unit 16).","y":0,"u":8},{"k":"닭","e":"chicken (animal)","x":"닭 한 마리를 사요.","t":"I buy one chicken.","h":"The animal (chicken). For the meat say 닭고기. 닭 한 마리 = one chicken.","y":0,"u":8},{"k":"닭고기","e":"chicken (meat)","x":"닭고기로 요리해요.","t":"I cook with chicken.","h":"닭 (chicken) + 고기 (meat). Compare 소고기 (beef), 돼지고기 (pork).","y":0,"u":8},{"k":"대","e":"counter for machines/vehicles","x":"자동차가 한 대 있어요.","t":"I have one car.","h":"Counter for machines/vehicles: 자동차 한 대, 컴퓨터 두 대, 버스 세 대.","y":0,"u":8},{"k":"마리","e":"counter for animals","x":"고양이 세 마리를 키워요.","t":"I raise three cats.","h":"Counter for animals: 개 한 마리, 고양이 두 마리. Use native numbers before it.","y":0,"u":8},{"k":"명","e":"counter for people","x":"학생이 열 명 있어요.","t":"There are ten students.","h":"Counter for people: 학생 세 명 = three students. Honorific version: 분 (unit 10).","y":0,"u":8},{"k":"물","e":"water","x":"물을 많이 마셔요.","t":"I drink a lot of water.","h":"Water. 물 좀 주세요 (unit 7). 물을 마셔요 = drink water.","y":0,"u":8},{"k":"병","e":"counter for bottles","x":"물 두 병 주세요.","t":"Two bottles of water, please.","h":"Counter for bottles: 물 한 병, 콜라 두 병. 한 병 (둘 -> 두, 하나 -> 한).","y":0,"u":8},{"k":"봉투","e":"envelope, paper/plastic bag","x":"봉투에 넣어 주세요.","t":"Please put it in a bag.","h":"Envelope/bag. 비닐봉투 = plastic bag (마트에서 100원).","y":0,"u":8},{"k":"빠르다","e":"to be fast","x":"이 버스는 빨라요.","t":"This bus is fast.","h":"빨라요 = fast (ㄹ irregular). Adverb 빨리 = quickly (unit 12). Opposite: 느리다.","y":0,"u":8},{"k":"사진","e":"photo","x":"사진을 찍어요.","t":"I take a photo.","h":"Photo. 사진을 찍다 = take a photo (unit 17: 사진을 찍지 마세요 = do not take photos).","y":0,"u":8},{"k":"상품","e":"product, item","x":"이 상품은 할인 중이에요.","t":"This product is on sale.","h":"Product/item for sale. 상품권 = gift certificate. 마트/백화점 word.","y":0,"u":8},{"k":"잔","e":"counter for cups/glasses","x":"커피 한 잔을 마셔요.","t":"I drink a cup of coffee.","h":"Counter for cups/glasses: 커피 한 잔, 물 두 잔. 컵 and 잔 often pair.","y":0,"u":8},{"k":"잡지","e":"magazine","x":"잡지를 읽어요.","t":"I read a magazine.","h":"Magazine. 잡지를 읽어요. Count with 권: 잡지 한 권.","y":0,"u":8},{"k":"장","e":"counter for sheets/paper","x":"종이 세 장 주세요.","t":"Three sheets of paper, please.","h":"Counter for flat sheets: 종이 한 장, 사진 두 장, 티셔츠 한 장 (clothes too!).","y":0,"u":8},{"k":"조각","e":"piece, slice","x":"케이크 한 조각을 먹어요.","t":"I eat a piece of cake.","h":"Piece/slice: 피자 한 조각, 케이크 두 조각. Not a pure counter, works like one.","y":0,"u":8},{"k":"채소","e":"vegetables","x":"시장에서 채소를 사요.","t":"I buy vegetables at the market.","h":"Vegetables. 채소를 사요 = buy vegetables. Also 야채 in speech.","y":0,"u":8},{"k":"청소기","e":"vacuum cleaner","x":"청소기로 청소해요.","t":"I clean with a vacuum cleaner.","h":"청소 (cleaning) + 기 (machine) = vacuum. 청소기를 돌리다 = run the vacuum.","y":0,"u":8},{"k":"커피","e":"coffee","x":"커피 한 잔 주세요.","t":"One cup of coffee, please.","h":"Loanword. 커피 한 잔 = one cup of coffee. Counter 잔 below.","y":0,"u":8},{"k":"할인","e":"discount","x":"지금 20% 할인해요.","t":"There is a 20% discount now.","h":"Discount. 할인이 있어요? = Is there a discount? 할인 마트 = discount mart.","y":0,"u":8},{"k":"걷다","e":"to walk","x":"집까지 걸었어요.","t":"I walked home.","h":"걸어요 = walk (ㄷ irregular: ㄷ -> ㄹ before vowel). 걸어서 가요 = go on foot.","y":0,"u":9},{"k":"공놀이를 하다","e":"to play ball","x":"운동장에서 공놀이를 했어요.","t":"We played ball on the field.","h":"공 (ball) + 놀이 (play) = ball games. 놀이 family: 불꽃놀이 (unit 12).","y":1,"u":9},{"k":"과일을 사다","e":"to buy fruit","x":"시장에서 과일을 샀어요.","t":"I bought fruit at the market.","h":"과일 = fruit. 사다 = buy -> 사요 / 샀어요. 과일을 샀어요 = bought fruit.","y":1,"u":9},{"k":"그렇지만","e":"but, however","x":"바빴어요. 그렇지만 즐거웠어요.","t":"I was busy. But it was fun.","h":"But/however, mid-formality. Family: 하지만 (unit 2) < 그렇지만 < 그런데 (soft).","y":0,"u":9},{"k":"백화점","e":"department store","x":"백화점에서 쇼핑했어요.","t":"I shopped at the department store.","h":"백화 (hundred goods) + 점 (store) = department store. Hyundai, Lotte, Shinsegae.","y":0,"u":9},{"k":"빨래를 하다","e":"to do laundry","x":"토요일에 빨래를 했어요.","t":"I did laundry on Saturday.","h":"빨래 = laundry. 빨래해요 = do laundry. 빨래방 (unit 4) = laundromat.","y":1,"u":9},{"k":"산에 가다","e":"to go to the mountains","x":"주말에 산에 갔어요.","t":"I went to the mountains on the weekend.","h":"산 = mountain. 산에 가요 = go hiking/to the mountains. 등산 (unit 12) = hiking.","y":1,"u":9},{"k":"산책하다","e":"to take a walk","x":"저녁에 산책했어요.","t":"I took a walk in the evening.","h":"산책해요 = take a walk. 공원에서 산책해요. Lighter than 걷다 (just walk).","y":0,"u":9},{"k":"쇼핑하다","e":"to shop","x":"주말에 쇼핑했어요.","t":"I went shopping on the weekend.","h":"Loanword verb. 쇼핑해요. 백화점에서 쇼핑해요 = shop at the department store.","y":0,"u":9},{"k":"시장","e":"market","x":"시장에서 먹을 것을 샀어요.","t":"I bought food at the market.","h":"Traditional market. 시장에서 사요 = buy at the market. Compare 마트 (modern store).","y":0,"u":9},{"k":"식사를 하다","e":"to have a meal","x":"가족하고 식사를 했어요.","t":"I had a meal with my family.","h":"식사 = meal (formal). 식사하셨어요? = Have you eaten? (polite greeting).","y":1,"u":9},{"k":"신발을 사다","e":"to buy shoes","x":"백화점에서 신발을 샀어요.","t":"I bought shoes at the department store.","h":"신발 = shoes. 신발을 신다 = put on shoes (신다 for feet). Count: 한 켤레 (pair).","y":1,"u":9},{"k":"아르바이트를 하다","e":"to work a part-time job","x":"편의점에서 아르바이트를 해요.","t":"I work part-time at a convenience store.","h":"From German Arbeit. 알바 for short - everyone says 알바. 알바해요.","y":1,"u":9},{"k":"이야기를 하다","e":"to talk, have a conversation","x":"친구하고 이야기를 했어요.","t":"I talked with my friend.","h":"이야기 (story/talk) + 하다. 이야기해요 = talk. Also 이야기하다 without 를.","y":1,"u":9},{"k":"자전거를 타다","e":"to ride a bicycle","x":"공원에서 자전거를 탔어요.","t":"I rode a bicycle in the park.","h":"타다 = ride (vehicles): 자전거, 버스, 배를 타다. Not for walking (걷다).","y":1,"u":9},{"k":"저녁을 먹다","e":"to eat dinner","x":"어제 저녁을 먹었어요.","t":"I ate dinner yesterday.","h":"저녁 = evening AND dinner. 저녁을 먹었어요 = ate dinner. Same: 아침, 점심.","y":1,"u":9},{"k":"전주","e":"Jeonju (city)","x":"전주에 여행을 갔어요.","t":"I traveled to Jeonju.","h":"City famous for 비빔밥 and 한옥 마을. 전라도 region.","y":0,"u":9},{"k":"전화를 받다","e":"to answer the phone","x":"전화를 받았어요.","t":"I answered the phone.","h":"받다 = receive/answer. 전화를 받아요 = answer the phone. Opposite: 전화를 걸다.","y":1,"u":9},{"k":"즐겁다","e":"to be enjoyable, joyful","x":"주말이 즐거웠어요.","t":"The weekend was fun.","h":"즐거워요 = enjoyable (ㅂ irregular). Compare 재미있다 (fun). 즐거운 주말!","y":0,"u":9},{"k":"집","e":"home","x":"집에서 쉬었어요.","t":"I rested at home.","h":"집에 가요 = go home. 집에서 쉬어요 = rest at home. 에 가요 vs 에서 있어요.","y":0,"u":9},{"k":"집에서 쉬다","e":"to rest at home","x":"어제 집에서 쉬었어요.","t":"I rested at home yesterday.","h":"쉬다 = rest. 쉬어요. 집에서 = at home (에서 for the action place).","y":1,"u":9},{"k":"차를 마시다","e":"to drink tea","x":"카페에서 차를 마셨어요.","t":"I drank tea at a cafe.","h":"차 = tea. 차를 마셔요. Compare 커피를 마시다 (unit 3). 마시다 = drink.","y":1,"u":9},{"k":"청소를 하다","e":"to clean","x":"아침에 청소를 했어요.","t":"I cleaned in the morning.","h":"청소 = cleaning. 청소해요 = clean. Same as 방을 청소하다 (unit 3).","y":1,"u":9},{"k":"축구를 하다","e":"to play soccer","x":"어제 축구를 했어요.","t":"I played soccer yesterday.","h":"축구 = soccer. 해요/했어요. Sports with 하다: 축구, 농구, 테니스(를 치다).","y":1,"u":9},{"k":"친구를 만나다","e":"to meet a friend","x":"지난 주말에 친구를 만났어요.","t":"I met my friend last weekend.","h":"만나다 = meet. 만나요 (present). 친구를 만났어요 = met a friend (past, unit 9).","y":1,"u":9},{"k":"카페","e":"cafe","x":"카페에서 이야기했어요.","t":"We talked at a cafe.","h":"카페에서 커피를 마셔요. 에서 = place where the action happens.","y":0,"u":9},{"k":"텔레비전을 보다","e":"to watch TV","x":"어제 텔레비전을 봤어요.","t":"I watched TV yesterday.","h":"보다 = see/watch. 봐요 (present): 텔레비전을 봐요.","y":1,"u":9},{"k":"한국어를 배우다","e":"to learn Korean","x":"작년부터 한국어를 배웠어요.","t":"I have been learning Korean since last year.","h":"배워요 = learn. 배우다 vs 공부하다: 배우다 = learn (skill), 공부하다 = study.","y":1,"u":9},{"k":"한복을 입다","e":"to wear hanbok","x":"한옥 마을에서 한복을 입었어요.","t":"I wore hanbok in the hanok village.","h":"한복 = traditional Korean clothing. 입어요 = wear. 한복을 입고 사진을 찍어요.","y":1,"u":9},{"k":"한옥 마을","e":"hanok village","x":"전주 한옥 마을에 갔어요.","t":"I went to the Jeonju Hanok Village.","h":"한옥 = traditional Korean house. 한옥 마을 = village of traditional houses.","y":1,"u":9},{"k":"회사","e":"company","x":"회사에서 일했어요.","t":"I worked at the company.","h":"회사에 다녀요 = go to work regularly (다니다 = attend/commute). 회사원 = office worker.","y":0,"u":9},{"k":"계시다","e":"to be, exist (honorific of 있다)","x":"할머니가 집에 계세요.","t":"My grandmother is at home.","h":"Honorific of 있다 (to be/stay). 할아버지가 계세요 = grandfather is (there).","y":0,"u":10},{"k":"고등학생","e":"high school student","x":"동생은 고등학생이에요.","t":"My younger sibling is a high school student.","h":"고등학교 (high school) + 생. Chain: 초등학생 - 중학생 - 고등학생 - 대학생.","y":0,"u":10},{"k":"나","e":"I, me (informal)","x":"나는 학생이에요.","t":"I am a student.","h":"I (informal). Polite form: 저. 나는 -> 저는 when speaking politely.","y":0,"u":10},{"k":"남동생","e":"younger brother","x":"남동생은 고등학생이에요.","t":"My younger brother is a high school student.","h":"남 (male) + 동생 (younger sibling). 동생 works alone when gender is clear.","y":0,"u":10},{"k":"높임말","e":"honorific speech","x":"할아버지께는 높임말을 써요.","t":"I use honorific speech with my grandfather.","h":"Honorific speech. 높임 (raising) + 말 (speech). This unit's core grammar topic.","y":0,"u":10},{"k":"누나","e":"older sister (of a male)","x":"누나는 회사원이에요.","t":"My older sister is an office worker.","h":"Older sister OF A MALE. Female speaker says 언니 instead.","y":0,"u":10},{"k":"돌아가시다","e":"to pass away (honorific)","x":"할아버지가 작년에 돌아가셨어요.","t":"My grandfather passed away last year.","h":"Honorific/euphemism for 죽다 (die). 돌아가셨어요 = passed away. Handle with care.","y":0,"u":10},{"k":"드시다","e":"to eat/drink (honorific of 먹다/마시다)","x":"커피를 드세요?","t":"Would you like coffee?","h":"Honorific of 먹다/마시다 (eat/drink). 드세요. More common than 잡수시다.","y":0,"u":10},{"k":"말씀하시다","e":"to speak (honorific of 말하다)","x":"선생님이 말씀하세요.","t":"The teacher is speaking.","h":"Honorific of 말하다 (speak). 말씀하세요. 말씀 = speech (honorific noun).","y":0,"u":10},{"k":"부모님","e":"parents (honorific)","x":"부모님은 미국에 계세요.","t":"My parents are in the USA.","h":"부모 (parents) + 님 (honorific suffix). 님 marks respect: 선생님, 부모님.","y":0,"u":10},{"k":"분","e":"counter for people (honorific)","x":"손님이 세 분 오셨어요.","t":"Three guests came.","h":"Honorific counter for people: 두 분 = two people (respected). Plain version: 명 (unit 8).","y":0,"u":10},{"k":"생신","e":"birthday (honorific of 생일)","x":"오늘은 어머니 생신이에요.","t":"Today is my mother's birthday.","h":"Honorific of 생일 (birthday). 할머니 생신 = grandmother's birthday. Never for yourself.","y":0,"u":10},{"k":"성함","e":"name (honorific of 이름)","x":"성함이 어떻게 되세요?","t":"What is your name?","h":"Honorific of 이름 (name). 성함이 어떻게 되세요? = What is your name? (formal).","y":0,"u":10},{"k":"아버지(아빠)","e":"father (dad)","x":"아버지는 요리를 잘하세요.","t":"My father cooks well.","h":"아버지 = father (formal), 아빠 = dad (casual). Honorific verb: 아버지는 계세요.","y":0,"u":10},{"k":"어머니(엄마)","e":"mother (mom)","x":"어머니는 학교에서 일하세요.","t":"My mother works at a school.","h":"어머니 = mother (formal), 엄마 = mom (casual). Pair with 아버지/아빠.","y":0,"u":10},{"k":"언니","e":"older sister (of a female)","x":"언니는 영어 강사예요.","t":"My older sister is an English instructor.","h":"Older sister OF A FEMALE. Also polite call for any older woman.","y":0,"u":10},{"k":"여동생","e":"younger sister","x":"여동생은 초등학생이에요.","t":"My younger sister is an elementary student.","h":"여 (female) + 동생 = younger sister. Family tree: 형/누나/오빠/언니 above, 동생 below.","y":0,"u":10},{"k":"연세","e":"age (honorific of 나이)","x":"연세가 어떻게 되세요?","t":"How old are you?","h":"Honorific of 나이 (age). 연세가 어떻게 되세요? = How old are you? (to elders).","y":0,"u":10},{"k":"오빠","e":"older brother (of a female)","x":"오빠는 의사예요.","t":"My older brother is a doctor.","h":"Older brother OF A FEMALE. Also used by women for older boyfriends.","y":0,"u":10},{"k":"외할머니","e":"maternal grandmother","x":"외할머니를 자주 만나요.","t":"I often meet my maternal grandmother.","h":"Mother's mother. 외 pattern only for grandparents: 외할아버지, 외할머니.","y":0,"u":10},{"k":"외할아버지","e":"maternal grandfather","x":"외할아버지는 고향에 계세요.","t":"My maternal grandfather is in my hometown.","h":"외 = maternal (mother's side). 외할아버지 = mother's father.","y":0,"u":10},{"k":"잡수시다","e":"to eat (honorific of 먹다)","x":"할머니, 진지 잡수세요.","t":"Grandmother, please eat.","h":"Honorific of 먹다 (eat). 잡수세요 = please eat (very respectful). Same as 드시다.","y":0,"u":10},{"k":"주무시다","e":"to sleep (honorific of 자다)","x":"할아버지는 주무세요.","t":"My grandfather is sleeping.","h":"Honorific of 자다 (sleep). 주무세요 = sleep (to elders). Exam favorite!","y":0,"u":10},{"k":"할머니","e":"grandmother","x":"할머니는 부산에 계세요.","t":"My grandmother is in Busan.","h":"Grandmother. Pair: 할아버지/할머니. Maternal side adds 외: 외할머니.","y":0,"u":10},{"k":"할아버지","e":"grandfather","x":"할아버지는 주무세요.","t":"My grandfather is sleeping.","h":"Grandfather (father's side default). Honorific verbs required: 계세요, 주무세요.","y":0,"u":10},{"k":"형","e":"older brother (of a male)","x":"형은 대학생이에요.","t":"My older brother is a university student.","h":"Older brother OF A MALE. Speaker's gender decides the word: male says 형, female says 오빠.","y":0,"u":10},{"k":"결혼식","e":"wedding ceremony","x":"토요일에 결혼식에 가요.","t":"I go to a wedding on Saturday.","h":"결혼 (marriage) + 식 (ceremony). 식 family: 졸업식, 결혼식. 결혼해요 = get married (18).","y":0,"u":11},{"k":"기분이 좋다","e":"to feel good, be in a good mood","x":"선물을 받아서 기분이 좋아요.","t":"I feel good because I received a gift.","h":"기분 = mood/feeling. 기분이 좋아요 = feel good. Opposite: 기분이 나쁘다.","y":1,"u":11},{"k":"노래를 부르다","e":"to sing a song","x":"생일 노래를 불러요.","t":"We sing the birthday song.","h":"부르다 = sing (also: to call out). 노래를 불러요. 노래방 (unit 4) = karaoke.","y":1,"u":11},{"k":"받다","e":"to receive","x":"생일 선물을 받았어요.","t":"I received a birthday present.","h":"받아요 = receive. Opposite: 주다. 선물을 받았어요 = received a gift.","y":0,"u":11},{"k":"보내다","e":"to send","x":"부모님께 사진을 보내요.","t":"I send photos to my parents.","h":"보내요 = send. 소포를 보내요 = send a parcel (unit 13). 문자를 보내다 = text.","y":0,"u":11},{"k":"선물","e":"gift, present","x":"부모님께 선물을 드려요.","t":"I give a gift to my parents.","h":"Gift. 선물을 주다/받다 = give/receive a gift. 선물을 보내다 = send a gift.","y":0,"u":11},{"k":"스승의 날","e":"Teachers' Day (May 15)","x":"스승의 날에 선생님께 카드를 드려요.","t":"On Teachers' Day I give a card to my teacher.","h":"Teachers' Day, May 15. 스승 = teacher/mentor (formal word).","y":1,"u":11},{"k":"어린이날","e":"Children's Day (May 5)","x":"어린이날에 아이들이 선물을 받아요.","t":"On Children's Day children receive gifts.","h":"Children's Day, May 5. 어린이 = child. National holiday, families go out.","y":0,"u":11},{"k":"어버이날","e":"Parents' Day (May 8)","x":"어버이날에 부모님께 꽃을 드려요.","t":"On Parents' Day I give flowers to my parents.","h":"Parents' Day, May 8 (오월 팔일). Give 카네이션 (carnations) and cards.","y":0,"u":11},{"k":"여성의 날","e":"Women's Day","x":"여성의 날에 꽃을 선물해요.","t":"On Women's Day I gift flowers.","h":"Women's Day. 여성 = woman/female. Compare 남성 (male).","y":1,"u":11},{"k":"졸업식","e":"graduation ceremony","x":"2월에 졸업식이 있어요.","t":"There is a graduation ceremony in February.","h":"졸업 (graduation) + 식 (ceremony). 졸업하다 = to graduate (unit 18).","y":0,"u":11},{"k":"주다","e":"to give","x":"친구에게 선물을 줘요.","t":"I give a present to my friend.","h":"줘요 = give. Honorific to elders: 드리다 (부모님께 드려요). 받다 = receive.","y":0,"u":11},{"k":"초대","e":"invitation","x":"파티에 초대해요.","t":"I invite them to the party.","h":"Invitation. 초대를 받다 = be invited. 초대하다 = to invite. 초대장 = invitation card.","y":0,"u":11},{"k":"초대장","e":"invitation card/letter","x":"초대장을 보내요.","t":"I send an invitation.","h":"초대 + 장 (card/letter). 결혼식 초대장 = wedding invitation.","y":0,"u":11},{"k":"축하하다","e":"to congratulate","x":"생일을 축하해요.","t":"I congratulate them on their birthday.","h":"축하해요 = congratulate. 생일 축하해요! = Happy birthday! Exam phrase.","y":0,"u":11},{"k":"카드를 쓰다","e":"to write a card","x":"생일 카드를 써요.","t":"I write a birthday card.","h":"쓰다 = write. 카드를 써요 = write a card. Two 카드 meanings: credit card / greeting card.","y":1,"u":11},{"k":"케이크","e":"cake","x":"생일 케이크를 사요.","t":"I buy a birthday cake.","h":"Loanword. 생일 케이크 = birthday cake. Count with 조각 (unit 8).","y":0,"u":11},{"k":"가족하고 외식하다","e":"to eat out with family","x":"가족하고 외식할 거예요.","t":"I will eat out with my family.","h":"외식 = eating out (외 outside + 식 meal). 외식해요. Opposite: 집에서 먹다.","y":1,"u":12},{"k":"강원도","e":"Gangwon Province","x":"강원도에서 스키를 탈 거예요.","t":"I will ski in Gangwon Province.","h":"Eastern mountain province. Skiing in winter, 설악산 national park (unit 17).","y":0,"u":12},{"k":"고향 음식을 먹다","e":"to eat hometown food","x":"고향 음식을 먹을 거예요.","t":"I will eat food from my hometown.","h":"고향 = hometown/home country. 고향 음식 = food from home. 먹어요 = eat.","y":1,"u":12},{"k":"고향 친구들을 만나다","e":"to meet friends from home","x":"고향 친구들을 만날 거예요.","t":"I will meet my friends from home.","h":"만나다 = meet -> 만나요/만났어요. 고향 친구 = friend from home.","y":1,"u":12},{"k":"공원에서 농구를 하다","e":"to play basketball at the park","x":"공원에서 농구를 할 거예요.","t":"I will play basketball at the park.","h":"농구 = basketball. 에서 = action location. 농구해요 = play basketball.","y":1,"u":12},{"k":"꽃구경을 하다","e":"to go flower viewing","x":"봄에 꽃구경을 할 거예요.","t":"I will go see the flowers in spring.","h":"꽃구경 = flower viewing. Spring activity: 벚꽃 구경 (cherry blossoms).","y":1,"u":12},{"k":"낚시를 하다","e":"to go fishing","x":"아빠하고 낚시를 할 거예요.","t":"I will go fishing with my dad.","h":"낚시 = fishing. 낚시해요 = go fishing. 낚시터 = fishing spot.","y":1,"u":12},{"k":"낮잠을 자다","e":"to take a nap","x":"점심 후에 낮잠을 잘 거예요.","t":"I will take a nap after lunch.","h":"낮잠 = nap (낮 daytime + 잠 sleep). 낮잠을 자요 = take a nap.","y":1,"u":12},{"k":"놀이 기구를 타다","e":"to ride amusement rides","x":"놀이 기구를 탈 거예요.","t":"I will ride the rides.","h":"놀이 기구 = amusement rides. 타다 = ride (same verb as riding a bus!).","y":1,"u":12},{"k":"동물을 구경하다","e":"to look at animals","x":"동물원에서 동물을 구경할 거예요.","t":"I will look at animals at the zoo.","h":"구경하다 = look around/sightsee. 동물원에서 동물을 구경해요.","y":1,"u":12},{"k":"등산을 하다","e":"to go hiking","x":"주말에 등산을 할 거예요.","t":"I will go hiking on the weekend.","h":"등산 = hiking/mountain climbing. Very popular in Korea. 등산해요.","y":1,"u":12},{"k":"문화 센터","e":"culture center","x":"문화 센터에서 요리를 배워요.","t":"I learn cooking at the culture center.","h":"센터 = center. Classes there: 한국 요리를 배워요 (unit 12).","y":0,"u":12},{"k":"배를 타다","e":"to ride a boat","x":"바다에서 배를 탈 거예요.","t":"I will ride a boat on the sea.","h":"배 = boat (also stomach! context decides). 배를 타요 = ride a boat.","y":1,"u":12},{"k":"부모님을 만나다","e":"to meet one's parents","x":"부모님을 만날 거예요.","t":"I will meet my parents.","h":"부모님 = parents (honorific 님). 만나러 가요 = go to meet.","y":1,"u":12},{"k":"부산","e":"Busan (city)","x":"부산에 여행을 갈 거예요.","t":"I will travel to Busan.","h":"Korea's second city, southeast coast. Famous for beaches (해운대) and seafood.","y":0,"u":12},{"k":"불꽃놀이를 보다","e":"to watch fireworks","x":"강에서 불꽃놀이를 볼 거예요.","t":"I will watch fireworks by the river.","h":"불꽃 (fireworks) + 놀이 (play) = fireworks show. 보다 = watch.","y":1,"u":12},{"k":"빨리","e":"quickly, fast","x":"빨리 준비해요.","t":"Get ready quickly.","h":"Quickly. 빨리 가요 = go quickly. Adjective form: 빠르다 (unit 8). 빨리빨리 culture!","y":0,"u":12},{"k":"수영을 하다","e":"to swim","x":"바다에서 수영을 할 거예요.","t":"I will swim in the sea.","h":"수영 = swimming. 수영해요 = swim. 수영장 = swimming pool.","y":1,"u":12},{"k":"아이하고 놀이공원에 가다","e":"to go to an amusement park with the kids","x":"아이하고 놀이공원에 갈 거예요.","t":"I will go to the amusement park with my kids.","h":"하고 = with (casual). 놀이공원 = amusement park (놀이 + 공원).","y":1,"u":12},{"k":"안산","e":"Ansan (city)","x":"안산에서 친구를 만날 거예요.","t":"I will meet a friend in Ansan.","h":"City near Seoul with a big international community (외국인 거주 지역).","y":0,"u":12},{"k":"여행을 가다","e":"to go on a trip","x":"휴가에 여행을 갈 거예요.","t":"I will go on a trip during the vacation.","h":"여행 = trip/travel. 여행을 가요 = go on a trip. Also 여행하다 = to travel.","y":1,"u":12},{"k":"인삼차","e":"ginseng tea","x":"할머니께 인삼차를 드릴 거예요.","t":"I will give ginseng tea to my grandmother.","h":"인삼 (ginseng) + 차 (tea). Korea is famous for 인삼. 차 family: 녹차, 생강차.","y":0,"u":12},{"k":"친구 집에 놀러 가다","e":"to go hang out at a friend's house","x":"친구 집에 놀러 갈 거예요.","t":"I will go hang out at my friend's house.","h":"놀러 가다 = go to hang out/visit for fun. 놀러 오세요 = come visit me!","y":1,"u":12},{"k":"친척","e":"relatives","x":"친척 집에 갈 거예요.","t":"I will go to my relatives' house.","h":"Relatives/extended family. 친척을 만나요 = meet relatives. Compare 가족 (close family).","y":0,"u":12},{"k":"캠핑을 하다","e":"to go camping","x":"강원도에서 캠핑을 할 거예요.","t":"I will go camping in Gangwon Province.","h":"캠핑 = camping (loanword). 캠핑해요. Related: 야영, 취사 (unit 17).","y":1,"u":12},{"k":"컴퓨터 게임을 하다","e":"to play computer games","x":"집에서 컴퓨터 게임을 할 거예요.","t":"I will play computer games at home.","h":"컴퓨터 게임 = computer games. 게임해요. PC방 (unit 4) is for this.","y":1,"u":12},{"k":"한국 요리를 배우다","e":"to learn Korean cooking","x":"문화 센터에서 한국 요리를 배울 거예요.","t":"I will learn Korean cooking at the culture center.","h":"배우다 = learn (skill). 한국 요리 = Korean cooking. 문화 센터 class.","y":1,"u":12},{"k":"한국어를 열심히 공부하다","e":"to study Korean hard","x":"방학에 한국어를 열심히 공부할 거예요.","t":"I will study Korean hard during the break.","h":"열심히 = hard/diligently (adverb). 열심히 공부해요 = study hard.","y":1,"u":12},{"k":"화장품","e":"cosmetics","x":"한국에서 화장품을 살 거예요.","t":"I will buy cosmetics in Korea.","h":"Cosmetics. 화장 (makeup) + 품 (goods). Popular gift: 화장품을 사다.","y":0,"u":12},{"k":"휴가","e":"vacation, leave","x":"이번 휴가에 뭐 할 거예요?","t":"What will you do this vacation?","h":"Vacation from work. 휴가에 뭐 할 거예요? Compare 휴일 (a public day off).","y":0,"u":12},{"k":"휴일","e":"holiday, day off","x":"휴일에 집에서 쉴 거예요.","t":"I will rest at home on my day off.","h":"Holiday/day off (calendar-based). 휴가 = your own leave, 휴일 = everyone's day off.","y":0,"u":12},{"k":"고속버스","e":"express/intercity bus","x":"고속버스로 고향에 가요.","t":"I go to my hometown by express bus.","h":"고속 (high speed) + 버스 = intercity bus. 고속 means express, not the bus speeding.","y":0,"u":13},{"k":"고속버스 터미널","e":"express bus terminal","x":"고속버스 터미널이 어디예요?","t":"Where is the express bus terminal?","h":"터미널 = terminal (loanword). 서울 고속버스 터미널 in 반포.","y":0,"u":13},{"k":"기차","e":"train","x":"기차로 부산에 가요.","t":"I go to Busan by train.","h":"Train. 기차를 타요. KTX is the fast one. Compare 지하철 (city subway).","y":0,"u":13},{"k":"기차역","e":"train station","x":"기차역에서 표를 사요.","t":"I buy a ticket at the train station.","h":"기차 + 역 = train station. 서울역 = Seoul Station.","y":0,"u":13},{"k":"남산","e":"Namsan (mountain in Seoul)","x":"주말에 남산에 가요.","t":"I go to Namsan on the weekend.","h":"남 (south) + 산 (mountain). Seoul's central mountain with the tower.","y":0,"u":13},{"k":"남산 서울 타워","e":"Namsan Seoul Tower","x":"남산 서울 타워에서 서울을 봐요.","t":"I see Seoul from Namsan Seoul Tower.","h":"Seoul landmark on 남산. Take the 케이블카 up. Also called N서울타워.","y":0,"u":13},{"k":"버스","e":"bus","x":"버스로 공항에 가요.","t":"I go to the airport by bus.","h":"버스를 타요 = ride the bus. 버스로 가요 = go BY bus (로 = means of transport).","y":0,"u":13},{"k":"비행기","e":"airplane","x":"비행기로 제주도에 가요.","t":"I go to Jeju by plane.","h":"비행 (flight) + 기 (machine) = airplane. 비행기를 타요. 공항 = airport.","y":0,"u":13},{"k":"소포","e":"parcel","x":"우체국에서 소포를 보내요.","t":"I send a parcel at the post office.","h":"Parcel/package. 소포를 보내다 = send a parcel (보내다, unit 11). At 우체국.","y":0,"u":13},{"k":"오토바이","e":"motorcycle","x":"오토바이는 빨라요.","t":"Motorcycles are fast.","h":"Loanword: auto + bike = motorcycle. 오토바이를 타요.","y":0,"u":13},{"k":"자동차","e":"car","x":"자동차로 출근해요.","t":"I commute by car.","h":"자동 (automatic) + 차 (vehicle) = car. 차 for short in speech.","y":0,"u":13},{"k":"자전거","e":"bicycle","x":"자전거로 가요.","t":"I go by bicycle.","h":"자전 (self-turning) + 거 (vehicle) = bicycle. 자전거를 타다 (unit 9).","y":0,"u":13},{"k":"전망대","e":"observatory, observation deck","x":"전망대에서 사진을 찍어요.","t":"I take photos at the observatory.","h":"전망 (view) + 대 (platform) = observatory. 전망대에서 서울을 봐요.","y":0,"u":13},{"k":"정류장","e":"bus stop","x":"정류장에서 버스를 기다려요.","t":"I wait for the bus at the stop.","h":"정류 (stopping) + 장 (place) = bus stop. 버스 정류장이 어디예요?","y":0,"u":13},{"k":"지하철","e":"subway","x":"지하철로 회사에 가요.","t":"I go to work by subway.","h":"지하 (underground) + 철 (rail) = subway. 지하철을 타다 / 지하철로 가다.","y":0,"u":13},{"k":"지하철역","e":"subway station","x":"지하철역이 가까워요.","t":"The subway station is close.","h":"역 = station. 지하철역이 어디예요? = Where is the subway station?","y":0,"u":13},{"k":"케이블카","e":"cable car","x":"케이블카를 타고 올라가요.","t":"I go up by cable car.","h":"Loanword (cable car). 케이블카를 타요 = ride the cable car.","y":0,"u":13},{"k":"택시","e":"taxi","x":"택시를 타고 집에 가요.","t":"I take a taxi home.","h":"택시를 타요 = ride a taxi. 택시를 잡다 = hail a taxi (unit 18).","y":0,"u":13},{"k":"환전하다","e":"to exchange money","x":"은행에서 환전해요.","t":"I exchange money at the bank.","h":"환전 = money exchange. 환전해요. 은행에서 환전해요 = exchange at the bank.","y":0,"u":13},{"k":"힘들다","e":"to be hard, tiring","x":"걸어서 가면 힘들어요.","t":"It is tiring if I walk.","h":"힘들어요 = hard/tiring. 힘 = strength + 들다. 힘들지만 재미있어요 (unit 18 title!).","y":0,"u":13},{"k":"가족 모임이 있다","e":"to have a family gathering","x":"일요일에 가족 모임이 있어요.","t":"I have a family gathering on Sunday.","h":"가족 모임 = family gathering. 있다 = have (an event). 모임이 있어요.","y":1,"u":14},{"k":"갑자기 일이 생기다","e":"to have something come up suddenly","x":"갑자기 일이 생겼어요.","t":"Something came up suddenly.","h":"갑자기 = suddenly. 생기다 = come up/arise. Something suddenly came up.","y":1,"u":14},{"k":"답장하다","e":"to reply (to a message)","x":"문자에 답장해요.","t":"I reply to the text message.","h":"답장 = reply (to a message/letter). 답장해요. 문자 답장 = text reply.","y":0,"u":14},{"k":"모임","e":"meeting, gathering","x":"토요일에 모임이 있어요.","t":"I have a gathering on Saturday.","h":"Gathering/meetup. 모임이 있어요 = I have a gathering. 모임에 가다 = attend one.","y":0,"u":14},{"k":"몸이 아프다","e":"to feel sick, ache","x":"몸이 아파서 못 가요.","t":"I can't go because I feel sick.","h":"몸 = body. 몸이 아파요 = I feel sick. Common excuse pattern: 아파서 못 가요.","y":1,"u":14},{"k":"새","e":"bird","x":"아침에 새가 울어요.","t":"A bird sings in the morning.","h":"Bird. Also means NEW as an adjective prefix (새 책 = new book). Context decides.","y":0,"u":14},{"k":"시험이 있다","e":"to have an exam","x":"내일 시험이 있어요.","t":"I have an exam tomorrow.","h":"시험 = exam/test. 시험이 있어요 = I have an exam. 시험을 보다 = take an exam.","y":1,"u":14},{"k":"야근을 하다","e":"to work overtime at night","x":"오늘 야근을 해요.","t":"I work overtime tonight.","h":"야근 = overtime at night (야 night + 근 work). 야근해요. Compare 출근/퇴근.","y":1,"u":14},{"k":"약속 시간에 늦다","e":"to be late for an appointment","x":"미안해요, 약속 시간에 늦었어요.","t":"Sorry, I was late for our appointment.","h":"늦다 = be late. 늦어요/늦었어요. Opposite: 일찍 (early). 늦어서 미안해요.","y":1,"u":14},{"k":"약속 시간을 정하다","e":"to set the meeting time","x":"약속 시간을 정해요.","t":"Let's set a time.","h":"정하다 = decide/set. 정해요. 약속 시간 = meeting time. See also 장소.","y":1,"u":14},{"k":"약속 장소를 바꾸다","e":"to change the meeting place","x":"약속 장소를 바꿔요.","t":"Let's change the place.","h":"바꾸다 = change/switch. 바꿔요. 바꾸다 vs 바뀌다: 바꾸다 = change something.","y":1,"u":14},{"k":"약속 장소를 정하다","e":"to set the meeting place","x":"약속 장소를 정해요.","t":"Let's decide on the place.","h":"장소 = place/venue. 약속 장소 = meeting place. 장소를 바꾸다 = change it.","y":1,"u":14},{"k":"약속을 지키다","e":"to keep a promise/appointment","x":"약속을 꼭 지켜요.","t":"I always keep my appointments.","h":"지키다 = keep/observe. 약속을 지켜요 = keep the appointment. Key phrase.","y":1,"u":14},{"k":"약속하다","e":"to make an appointment/promise","x":"친구하고 약속해요.","t":"I make plans with my friend.","h":"약속 = promise/appointment. 약속해요 = make plans. 약속이 있어요 = I have plans.","y":0,"u":14},{"k":"일이 많다","e":"to have a lot of work","x":"오늘 일이 많아요.","t":"I have a lot of work today.","h":"일 = work + 많다 = a lot. 일이 많아요 = I have lots of work. Excuse #1.","y":1,"u":14},{"k":"직장 모임","e":"work gathering","x":"오늘 직장 모임이 있어요.","t":"I have a work gathering today.","h":"직장 = workplace. 직장 모임 = work gathering. Compare 회식 (with food/drink).","y":0,"u":14},{"k":"회식을 하다","e":"to have a company dinner","x":"저녁에 회식을 해요.","t":"We have a company dinner in the evening.","h":"회식해요 = have a company dinner. 회식이 있어서 늦어요 = late because of 회식.","y":1,"u":14},{"k":"회식이 있다","e":"to have a company dinner","x":"금요일에 회식이 있어요.","t":"There is a company dinner on Friday.","h":"회식 = company dinner (회 company + 식 meal). Korean work culture staple.","y":1,"u":14},{"k":"가을","e":"autumn, fall","x":"가을에는 단풍이 예뻐요.","t":"The autumn leaves are pretty in fall.","h":"Autumn. 가을에 단풍이 들어요 = leaves turn color. 쌀쌀해요 = chilly.","y":0,"u":15},{"k":"겨울","e":"winter","x":"겨울에는 눈이 와요.","t":"It snows in winter.","h":"Winter. 겨울에 추워요 = cold in winter. 눈이 와요 = it snows.","y":0,"u":15},{"k":"계절","e":"season","x":"한국은 계절이 넷이에요.","t":"Korea has four seasons.","h":"Season. 사계절 = the four seasons. 좋아하는 계절 = favorite season.","y":0,"u":15},{"k":"구름이 끼다","e":"to become cloudy","x":"오후에 구름이 꼈어요.","t":"It became cloudy in the afternoon.","h":"구름 = cloud + 끼다 = form/wear. 구름이 껴요 = it gets cloudy. 끼다 is odd: learn as a set.","y":1,"u":15},{"k":"꽃이 많이 피다","e":"for many flowers to bloom","x":"봄에 꽃이 많이 펴요.","t":"Many flowers bloom in spring.","h":"피다 = bloom. 꽃이 펴요 = flowers bloom. Spring word, pairs with 봄.","y":1,"u":15},{"k":"날씨","e":"weather","x":"오늘 날씨가 정말 덥네요.","t":"The weather is really hot today.","h":"Weather. 날씨가 어때요? = How is the weather? Classic small talk + exam topic.","y":0,"u":15},{"k":"눈썰매를 타다","e":"to go sledding","x":"겨울에 눈썰매를 타요.","t":"I go sledding in winter.","h":"눈썰매 = sled (눈 snow + 썰매 sled). 눈썰매를 타요 = go sledding. Winter.","y":1,"u":15},{"k":"눈이 오다","e":"to snow","x":"겨울에 눈이 와요.","t":"It snows in winter.","h":"눈 = snow + 오다. 눈이 와요 = it snows. Careful: 눈 also means EYE (unit 16).","y":1,"u":15},{"k":"단풍이 아름답다","e":"the autumn foliage is beautiful","x":"가을에 단풍이 아름다워요.","t":"The fall foliage is beautiful.","h":"단풍 = autumn leaves. 아름다워요 = beautiful. Autumn word, pairs with 가을.","y":1,"u":15},{"k":"덥다","e":"to be hot","x":"오늘 정말 더워요.","t":"It is really hot today.","h":"더워요 = hot (ㅂ irregular: ㅂ -> 우 -> 워). For weather. Opposite: 춥다 (추워요).","y":0,"u":15},{"k":"따뜻하다","e":"to be warm","x":"봄에는 따뜻해요.","t":"It is warm in spring.","h":"따뜻해요 = warm. For weather AND things (따뜻한 커피). Between 덥다 and 쌀쌀하다.","y":0,"u":15},{"k":"맑다","e":"to be clear (weather)","x":"오늘 하늘이 맑아요.","t":"The sky is clear today.","h":"맑아요 = clear skies. Opposite: 흐리다. 하늘이 맑아요 = the sky is clear.","y":0,"u":15},{"k":"매우","e":"very, extremely","x":"오늘 매우 더워요.","t":"It is very hot today.","h":"Very (written/formal). 매우 좋아요. Casual versions: 아주, 정말, 진짜.","y":0,"u":15},{"k":"바닷가","e":"beach, seaside","x":"여름에 바닷가에 가요.","t":"I go to the beach in summer.","h":"바다 (sea) + 가 (edge) = beach/seaside. 여름에 바닷가에 가요. Compare 바다.","y":0,"u":15},{"k":"바람이 불다","e":"to be windy","x":"오늘 바람이 불어요.","t":"It is windy today.","h":"바람 = wind + 불다 = blow. 바람이 불어요 = the wind blows. Set phrase.","y":1,"u":15},{"k":"봄","e":"spring","x":"봄에는 꽃이 펴요.","t":"Flowers bloom in spring.","h":"Spring. 봄에 꽃이 펴요 = flowers bloom in spring. Warm: 따뜻해요.","y":0,"u":15},{"k":"비가 오다","e":"to rain","x":"밖에 비가 와요.","t":"It is raining outside.","h":"비 = rain + 오다 = come. 비가 와요 = it rains. Weather + 오다 pattern.","y":1,"u":15},{"k":"사계절","e":"the four seasons","x":"한국은 사계절이 뚜렷해요.","t":"Korea's four seasons are distinct.","h":"사 (four) + 계절 = four seasons. 봄 - 여름 - 가을 - 겨울.","y":0,"u":15},{"k":"스키를 타다","e":"to ski","x":"겨울에 스키를 타요.","t":"I ski in winter.","h":"스키 = ski (loanword). 스키를 타요 = ski. 스키장 = ski resort. 강원도 in winter.","y":1,"u":15},{"k":"쌀쌀하다","e":"to be chilly","x":"가을 아침은 쌀쌀해요.","t":"Autumn mornings are chilly.","h":"쌀쌀해요 = chilly. Cooler than 시원하다, warmer than 춥다. Autumn word.","y":0,"u":15},{"k":"안개가 끼다","e":"to be foggy","x":"아침에 안개가 꼈어요.","t":"It was foggy in the morning.","h":"안개 = fog. 안개가 껴요 = it is foggy. Same 끼다 pattern as 구름.","y":1,"u":15},{"k":"여름","e":"summer","x":"여름에는 더워요.","t":"It is hot in summer.","h":"Summer. 여름에 더워요 = hot in summer. 팥빙수 season (unit 18).","y":0,"u":15},{"k":"인구","e":"population","x":"서울은 인구가 많아요.","t":"Seoul has a large population.","h":"인 (people) + 구 (mouth/count) = population. 인구가 많아요 = large population.","y":0,"u":15},{"k":"천둥/번개가 치다","e":"to thunder/lightning","x":"밤에 천둥/번개가 쳤어요.","t":"There was thunder and lightning at night.","h":"천둥 = thunder, 번개 = lightning. 치다 = strike. 천둥이 쳐요 = it thunders.","y":1,"u":15},{"k":"춥다","e":"to be cold","x":"겨울에는 추워요.","t":"It is cold in winter.","h":"추워요 = cold (ㅂ irregular). Weather only; for things use 차갑다.","y":0,"u":15},{"k":"흐리다","e":"to be cloudy","x":"내일은 흐릴 거예요.","t":"It will be cloudy tomorrow.","h":"흐려요 = cloudy/overcast. Opposite: 맑다. Compare 구름이 끼다 (clouds form).","y":0,"u":15},{"k":"귀","e":"ear","x":"귀가 아파요.","t":"My ear hurts.","h":"Ear. 귀가 아파요 = earache. 이비인후과 = ear-nose-throat clinic.","y":0,"u":16},{"k":"내과","e":"internal medicine department","x":"내과에서 진료를 받아요.","t":"I get treated at internal medicine.","h":"내 (inside) + 과 (department) = internal medicine. 과 = department pattern.","y":0,"u":16},{"k":"눈","e":"eye","x":"눈이 피곤해요.","t":"My eyes are tired.","h":"Eye. 눈이 아파요 -> 안과. Homonym: 눈 = snow (unit 15). Context decides.","y":0,"u":16},{"k":"다리","e":"leg","x":"다리가 아파요.","t":"My leg hurts.","h":"Leg. Confusable: 다리 = bridge too. 다리가 아파요 = my leg hurts.","y":0,"u":16},{"k":"다리가 부러지다","e":"to break one's leg","x":"다리가 부러졌어요.","t":"I broke my leg.","h":"부러지다 = break (bone). 부러져요/부러졌어요. 정형외과로 가요.","y":1,"u":16},{"k":"목","e":"throat, neck","x":"목이 아파요.","t":"My throat hurts.","h":"Throat OR neck. 목이 아파요 = sore throat. 목소리 = voice (목 + 소리).","y":0,"u":16},{"k":"무릎","e":"knee","x":"무릎이 아파요.","t":"My knee hurts.","h":"Knee. 무릎이 아파요 = knee hurts. Spelling trap: 무릎 not 무릅.","y":0,"u":16},{"k":"발","e":"foot","x":"발이 아파요.","t":"My foot hurts.","h":"Foot. 발가락 = toe. 발이 아파요 = my foot hurts. Do not confuse with 팔 (arm).","y":0,"u":16},{"k":"배","e":"stomach, belly","x":"배가 아파서 병원에 가요.","t":"My stomach hurts, so I go to the hospital.","h":"Stomach. 배가 아파요 = my stomach hurts. Homonyms: 배 = boat, 배 = pear. Context!","y":0,"u":16},{"k":"비타민 시(C)","e":"vitamin C","x":"비타민 C를 먹어요.","t":"I take vitamin C.","h":"비타민 = vitamin (loanword). C reads 씨. 감기에 비타민 C = vitamin C for a cold.","y":0,"u":16},{"k":"생강차","e":"ginger tea","x":"감기에 생강차가 좋아요.","t":"Ginger tea is good for a cold.","h":"생강 (ginger) + 차 (tea). Koreans drink it when sick/cold. 차 family: 녹차, 인삼차.","y":0,"u":16},{"k":"손","e":"hand","x":"손을 씻어요.","t":"I wash my hands.","h":"Hand. 손가락 = finger. Pair with 발 (foot): 손 = hand, 발 = foot.","y":0,"u":16},{"k":"안과","e":"eye clinic","x":"안과에서 눈을 검사해요.","t":"I get my eyes checked at the eye clinic.","h":"안 (eye) + 과 = eye clinic. 눈이 아프면 안과. Do not confuse with 이비인후과.","y":0,"u":16},{"k":"이","e":"tooth","x":"이가 아파요. 치과에 가요.","t":"My tooth hurts. I go to the dentist.","h":"Tooth. 이가 아파요 = toothache -> 치과. Homonym: 이 = Sino number 2 (unit 5).","y":0,"u":16},{"k":"이비인후과","e":"ENT (ear, nose, throat) clinic","x":"감기로 이비인후과에 가요.","t":"I go to the ENT clinic for a cold.","h":"이(ear) 비(nose) 인후(throat) + 과 = ENT clinic. 코/귀/목 problems go here.","y":0,"u":16},{"k":"정형외과","e":"orthopedics","x":"다리가 아파서 정형외과에 가요.","t":"My leg hurts, so I go to orthopedics.","h":"정형 (orthopedic) + 외과 (surgery) = orthopedics. Broken bones: 다리가 부러지다.","y":0,"u":16},{"k":"치과","e":"dental clinic","x":"치과에 가요.","t":"I go to the dentist.","h":"치 (tooth) + 과 = dental clinic. 이가 아프면 치과에 가요.","y":0,"u":16},{"k":"코","e":"nose","x":"코가 막혀요.","t":"My nose is stuffy.","h":"Nose. 코가 막혀요 = stuffy nose. 이비인후과 (ENT). Compare 귀 (ear), 입 (mouth).","y":0,"u":16},{"k":"팔","e":"arm","x":"팔을 다쳤어요.","t":"I hurt my arm.","h":"Arm. Homonym: 팔 = Sino number 8 (unit 5). 팔이 아파요 = my arm hurts.","y":0,"u":16},{"k":"푹 쉬다","e":"to rest well","x":"집에서 푹 쉬세요.","t":"Rest well at home.","h":"푹 = deeply/thoroughly (adverb). 푹 쉬세요 = rest well. What Koreans say to the sick.","y":1,"u":16},{"k":"허리","e":"waist, lower back","x":"허리가 아파요.","t":"My back hurts.","h":"Waist/lower back. 허리가 아파요 = back pain. Common complaint word.","y":0,"u":16},{"k":"경찰서","e":"police station","x":"경찰서에 가요.","t":"I go to the police station.","h":"경찰 (police) + 서 (office) = police station. Lost things and 신고 (reports) here.","y":0,"u":17},{"k":"국제 운전면허증을 받다","e":"to get an international driver's license","x":"국제 운전면허증을 받아요.","t":"I get an international driver's license.","h":"운전면허증 = driver's license. 받다 = receive/get. 국제 = international.","y":1,"u":17},{"k":"꽃을 만지다","e":"to touch flowers","x":"꽃을 만지지 마세요.","t":"Do not touch the flowers.","h":"만지다 = touch. 만져요. 꽃을 만지지 마세요 = do not touch the flowers.","y":1,"u":17},{"k":"담배를 피우다","e":"to smoke","x":"여기에서 담배를 피우지 마세요.","t":"Do not smoke here.","h":"담배 = cigarette + 피우다 = smoke (burn). 피워요. 흡연 = smoking (formal sign word).","y":1,"u":17},{"k":"동물원","e":"zoo","x":"동물원에서 먹이를 주지 마세요.","t":"Do not feed the animals at the zoo.","h":"동물 (animal) + 원 (park) = zoo. 원 pattern: 공원, 동물원, 놀이공원 (12).","y":0,"u":17},{"k":"등록하다","e":"to register","x":"외국인 등록을 해요.","t":"I do my alien registration.","h":"등록 = registration. 등록해요 = register. 외국인 등록 = alien registration (unit 18).","y":0,"u":17},{"k":"뛰다","e":"to run","x":"여기에서 뛰지 마세요.","t":"Do not run here.","h":"뛰어요 = run. Compare 걷다 (walk, unit 9). 여기에서 뛰지 마세요 = do not run here.","y":0,"u":17},{"k":"박물관","e":"museum","x":"박물관에서 사진을 찍지 마세요.","t":"Do not take photos in the museum.","h":"박물 (wide things) + 관 (hall) = museum. 관 pattern: 영화관, 박물관, 미술관 (art).","y":0,"u":17},{"k":"설악산 국립 공원","e":"Seoraksan National Park","x":"설악산 국립 공원에 갔어요.","t":"I went to Seoraksan National Park.","h":"설악산 = famous mountain in 강원도. 국립 공원 = national park.","y":0,"u":17},{"k":"센터 사무실","e":"center office","x":"센터 사무실에 가세요.","t":"Go to the center office.","h":"사무실 = office (사무 office work + 실 room). 실 pattern: 미용실, 사무실.","y":0,"u":17},{"k":"수영반","e":"swimming class","x":"수영반에 등록해요.","t":"I register for the swimming class.","h":"수영 (swimming) + 반 (class) = swimming class. 반 = class/group at centers.","y":0,"u":17},{"k":"쓰레기 투기","e":"illegal dumping of trash","x":"쓰레기 투기를 하지 마세요.","t":"Do not dump trash illegally.","h":"투기 = dumping. 쓰레기 투기 = illegal dumping. Sign word: 투기 금지 (no dumping).","y":0,"u":17},{"k":"쓰레기를 버리다","e":"to throw away trash","x":"쓰레기를 버리지 마세요.","t":"Do not throw trash here.","h":"쓰레기 = trash + 버리다 = throw away. 버려요. 쓰레기를 버리지 마세요.","y":1,"u":17},{"k":"아래층","e":"downstairs, floor below","x":"아래층에 있어요.","t":"It is downstairs.","h":"아래 (below) + 층 = the floor below. 아래층에 살아요 = live downstairs.","y":0,"u":17},{"k":"야영","e":"camping out","x":"여기에서 야영하지 마세요.","t":"Do not camp here.","h":"Camping out (야 field + 영 camp). 야영 금지 = no camping. Compare 캠핑 (loanword).","y":0,"u":17},{"k":"역사 공부를 하다","e":"to study history","x":"한국 역사 공부를 해요.","t":"I study Korean history.","h":"역사 공부 = history study. 공부하다 = study (unit 3). 역사를 공부해요.","y":1,"u":17},{"k":"역사 박물관","e":"history museum","x":"역사 박물관에 갔어요.","t":"I went to the history museum.","h":"역사 = history. 역사 박물관 = history museum. 국립중앙박물관 in Seoul.","y":0,"u":17},{"k":"오른쪽","e":"right side","x":"오른쪽으로 가세요.","t":"Go to the right.","h":"Right side. 오른쪽으로 가세요 = go right. Pair with 왼쪽. 쪽 = side/direction.","y":0,"u":17},{"k":"왼쪽","e":"left side","x":"왼쪽으로 도세요.","t":"Turn left.","h":"Left side. 왼쪽에 있어요 = it is on the left. Directions: 오른쪽/왼쪽/직진 (straight).","y":0,"u":17},{"k":"위층","e":"upstairs, floor above","x":"위층으로 가세요.","t":"Go upstairs.","h":"위 (above) + 층 (floor) = the floor above. 층 counter: unit 5. Opposite: 아래층.","y":0,"u":17},{"k":"잔디밭에 들어가다","e":"to go on the grass","x":"잔디밭에 들어가지 마세요.","t":"Do not go on the grass.","h":"잔디밭 = lawn (잔디 grass + 밭 field). 들어가다 = enter. 들어가지 마세요.","y":1,"u":17},{"k":"주민 센터","e":"community center (district office)","x":"주민 센터에서 등록해요.","t":"I register at the community center.","h":"주민 (resident) + 센터 = district community office. For 등록 and documents.","y":0,"u":17},{"k":"주차장","e":"parking lot","x":"여기는 주차장이에요.","t":"This is a parking lot.","h":"주차 (parking) + 장 (place) = parking lot. 장 pattern: 정류장, 운동장.","y":0,"u":17},{"k":"주차하다","e":"to park (a car)","x":"여기에 주차하지 마세요.","t":"Do not park here.","h":"주차해요 = park. 여기에 주차하지 마세요 = do not park here. 지 마세요 = prohibition.","y":0,"u":17},{"k":"취사","e":"cooking (in parks/campgrounds)","x":"여기에서 취사하지 마세요.","t":"Do not cook here.","h":"Cooking (on campgrounds). 취사 금지 = no cooking. Sign vocabulary, formal.","y":0,"u":17},{"k":"캠핑","e":"camping","x":"주말에 캠핑을 해요.","t":"I go camping on the weekend.","h":"","y":0,"u":17},{"k":"환전하다","e":"to exchange money","x":"공항에서 환전해요.","t":"I exchange money at the airport.","h":"환전 = money exchange. 환전해요. 은행에서 환전해요 = exchange at the bank.","y":0,"u":17},{"k":"24시간 배달이 되다","e":"to have 24-hour delivery","x":"한국은 24시간 배달이 돼요.","t":"Korea has 24-hour delivery.","h":"배달 = delivery. 배달이 되다 = delivery is available. 배달해요? = do you deliver?","y":1,"u":18},{"k":"건강 보험이 되다","e":"to be covered by health insurance","x":"직장에 다니면 건강 보험이 돼요.","t":"If you work, you get health insurance.","h":"건강 보험 = health insurance. 되다 = become/be covered. 보험이 돼요 = you are covered.","y":1,"u":18},{"k":"결혼하다","e":"to get married","x":"내년에 결혼해요.","t":"I get married next year.","h":"결혼해요 = get married. 결혼식 = wedding (unit 11). Past: 결혼했어요 = is married.","y":0,"u":18},{"k":"교통 카드","e":"transportation card","x":"교통 카드로 버스를 타요.","t":"I ride the bus with a transportation card.","h":"교통 (traffic) + 카드 = transit card (T-money). Tap on 버스 and 지하철.","y":0,"u":18},{"k":"대중교통 수단을 이용하다","e":"to use public transportation","x":"대중교통 수단을 이용해요.","t":"I use public transportation.","h":"대중교통 = public transport. 수단 = means. 이용하다 = use. Formal phrase.","y":1,"u":18},{"k":"문을 닫다","e":"to close the door","x":"추우니까 문을 닫으세요.","t":"It is cold, so close the door.","h":"닫다 = close. 닫으세요. 추우니까 문을 닫으세요 = it is cold, so close the door.","y":1,"u":18},{"k":"문을 열다","e":"to open the door","x":"창문하고 문을 여세요.","t":"Open the windows and the door.","h":"열다 = open. 여세요 (polite request). Opposite: 닫다. 창문을 열다 = open the window.","y":1,"u":18},{"k":"방학이 있다","e":"to have a school vacation","x":"여름에 방학이 있어요.","t":"There is a vacation in summer.","h":"방학 = school vacation. 방학이 있어요 = there is a break. Compare 휴가 (work leave).","y":1,"u":18},{"k":"버스 전용 차로","e":"bus-only lane","x":"이 길은 버스 전용 차로예요.","t":"This road is a bus-only lane.","h":"전용 = exclusive use. 차로 = traffic lane. Blue lane: buses only. 전용 pattern word.","y":1,"u":18},{"k":"쓰레기봉투를 팔다","e":"to sell trash bags","x":"마트에서 쓰레기봉투를 팔아요.","t":"They sell trash bags at the mart.","h":"팔다 = sell. 팔아요. 쓰레기봉투 = official trash bag. Buy at 마트/편의점.","y":1,"u":18},{"k":"약을 팔다","e":"to sell medicine","x":"약국에서 약을 팔아요.","t":"They sell medicine at the pharmacy.","h":"팔다 = sell. Opposite: 사다 (buy). 약국에서 약을 팔아요 = pharmacy sells medicine.","y":1,"u":18},{"k":"외국인 등록증이 필요하다","e":"to need an alien registration card","x":"은행 계좌를 만들 때 외국인 등록증이 필요해요.","t":"You need an alien registration card to open a bank account.","h":"외국인 등록증 = ARC (alien registration card). 필요해요 = need. Bank/phone need it.","y":1,"u":18},{"k":"의식주","e":"food, clothing and shelter (basic necessities)","x":"한국의 의식주 문화를 배워요.","t":"I learn about Korean food, clothing and housing culture.","h":"의 (clothing) 식 (food) 주 (housing) = the three basic needs. One word for all three.","y":0,"u":18},{"k":"익숙하다","e":"to be familiar, used to","x":"한국 음식에 익숙해요.","t":"I am used to Korean food.","h":"익숙해요 = familiar/used to. 에 익숙하다 = used to something. 반대: 낯설다 (unfamiliar).","y":0,"u":18},{"k":"입학하다","e":"to enter a school","x":"아이가 학교에 입학해요.","t":"My child starts school.","h":"입 (enter) + 학 (school) = enter school. 입학해요. Opposite: 졸업하다.","y":0,"u":18},{"k":"자전거 도로","e":"bicycle lane/road","x":"자전거 도로에서 자전거를 타요.","t":"I ride my bike on the bicycle lane.","h":"자전거 (bicycle) + 도로 (road) = bike lane. 도로 = road (unit vocabulary).","y":1,"u":18},{"k":"점심시간","e":"lunch time","x":"점심시간이 12시예요.","t":"Lunch time is at 12.","h":"점심 (lunch) + 시간 (time) = lunchtime. 점심을 먹다 = eat lunch (아침/점심/저녁).","y":0,"u":18},{"k":"졸업하다","e":"to graduate","x":"대학교를 졸업해요.","t":"I graduate from university.","h":"졸업해요 = graduate. 졸업식 = graduation ceremony (unit 11). Pair with 입학하다.","y":0,"u":18},{"k":"중국어","e":"Chinese language","x":"중국어를 배워요.","t":"I learn Chinese.","h":"중국 (China) + 어 (language). Language family: 한국어, 영어 (1), 중국어, 일본어.","y":0,"u":18},{"k":"택시를 잡다","e":"to catch/hail a taxi","x":"길에서 택시를 잡아요.","t":"I catch a taxi on the street.","h":"잡다 = catch/grab. 택시를 잡아요 = hail a taxi. 잡다 also: 손을 잡다 (hold hands).","y":1,"u":18},{"k":"팥빙수","e":"patbingsu (red bean shaved ice)","x":"여름에 팥빙수를 먹어요.","t":"I eat patbingsu in summer.","h":"팥 (red bean) + 빙수 (shaved ice) = summer dessert. 여름에 먹어요.","y":0,"u":18},{"k":"편하다","e":"to be comfortable, convenient","x":"한국 생활이 편해요.","t":"Life in Korea is convenient.","h":"편해요 = comfortable/convenient. 편의점 (unit 4) shares 편 (convenient). 반대: 불편하다.","y":0,"u":18},{"k":"평일","e":"weekday","x":"평일에 일해요.","t":"I work on weekdays.","h":"평 (ordinary) + 일 (day) = weekday. Opposite: 주말 (unit 4). 평일에 일해요.","y":0,"u":18}]};
